// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Zaman serileri, endeks sayılar, baz yılı, hareketli ortalamalar, mevsimsel düzeltme ve demografik oran hesapları (orta).
const ozStatistics16Orta = <(String, String, List<String>, String)>[
  ('Toplamsal zaman serisi ayrıştırma modelinde Y = T + S + C + I eşitliği kullanılır. Bir perakende mağazasının üçüncü çeyrek gerçek satışı 480 bin TL, trend değeri 410 bin TL, konjonktürel etkisi +15 bin TL ve düzensiz şok etkisi -5 bin TL ise mevsimsel bileşen (S) kaç bin TL\'dir?', '+60 bin TL', ['+50 bin TL', '+70 bin TL', '-60 bin TL'], 'Toplamsal modelde Y = T + S + C + I olduğundan 480 = 410 + S + 15 - 5 yazılır; buradan 480 = 420 + S ve S = +60 bin TL bulunur.'),
  ('Çarpımsal ayrıştırma modeline (Y = T × S × C × I) göre modellenen bir elektrik tüketim serisinde trend değeri 500 MWh, mevsimsel çarpan 1,20, konjonktürel çarpan 0,90 ve rastlantısal çarpan 1,00 olduğunda gözlenen tüketim kaç MWh olur?', '540 MWh', ['510 MWh', '550 MWh', '600 MWh'], 'Çarpımsal modelde bileşenler birbiriyle çarpılır: 500 × 1,20 = 600 ve 600 × 0,90 × 1,00 = 540 MWh elde edilir.'),
  ('Zaman içinde ortalaması yükselen bir satış serisinde yaz ve kış ayları arasındaki farkın mutlak tutar olarak giderek açıldığı, ancak trende oranla yüzdesel genişliğinin sabit kaldığı görülüyorsa hangi ayrıştırma yapısı tercih edilmelidir?', 'Çarpımsal ayrıştırma modeli', ['Toplamsal ayrıştırma modeli', 'Sabit ortalamalı durağan model', 'Yalnızca doğrusal trend modeli'], 'Mevsimsel dalga boyunun serinin düzeyiyle (trendle) orantılı biçimde büyüdüğü durumlarda çarpımsal model, sabit genlikte kaldığı durumlarda toplamsal model uygundur.'),
  ('Y = T × S × C × I biçimindeki pozitif değerli çarpımsal bir zaman serisi modelini doğrusal ve toplamsal bir yapıya dönüştürmek için analistlerin başvurduğu standart matematiksel işlem hangisidir?', 'Serinin doğal logaritmasını almak', ['Gözlemlerin karesini hesaplamak', 'Her terime sabit bir sayı eklemek', 'Değerleri aritmetik ortalamaya bölmek'], 'Çarpımın logaritması terimlerin logaritmaları toplamına eşit olduğundan ln(Y) = ln(T) + ln(S) + ln(C) + ln(I) dönüşümü modeli toplamsal hale getirir.'),
  ('Mevsimsel ve konjonktürel dalgalanmaların her ikisi de zaman serisinde iniş çıkışlar yaratır. Bu iki bileşeni birbirinden ayıran en temel istatistiksel ölçüt nedir?', 'Tekrarlanma periyodunun sabitliği ve süresi', ['Gözlem sayısının tek veya çift olması', 'Yalnızca tarım sektöründe görülmesi', 'Serinin negatif değerler alabilmesi'], 'Mevsimsel hareketler bir yıl içinde sabit ve bilinen periyotlarla yinelenirken, konjonktürel dalgalar bir yıldan uzun ve değişken sürelidir.'),
  ('Bir zaman serisinin ortalamasının, varyansının ve gecikmeli kovaryans yapısının zaman boyunca değişmeden sabit kalması özelliğine ne ad verilir?', 'Zayıf anlamda durağanlık', ['Mevsimsel genlik artışı', 'Üstel büyüme eğilimi', 'Yapısal rejim kırılması'], 'Ortalaması ve varyansı zamana bağlı olmayan, otokovaryansı ise yalnızca gecikme uzunluğuna bağlı olan seriler kovaryans durağan (zayıf durağan) kabul edilir.'),
  ('Doğrusal trend denklemi T_t = 120 + 4,5t (t = 1, 2, 3, ... çeyrek dönem) olarak tahmin edilen bir kargo şirketinin t = 12. çeyrekteki gerçek gönderi hacmi 165 bin paket olmuştur. Trendden sapma (Y_12 - T_12) kaç bin pakettir?', '-9 bin paket', ['+9 bin paket', '-11 bin paket', '+6 bin paket'], 't = 12 için trend tahmini T_12 = 120 + 4,5 × 12 = 120 + 54 = 174 bin pakettir. Gerçekleşen değer 165 bin olduğundan fark 165 - 174 = -9 bin pakettir.'),
  ('Merkez bankasının para politikası rejimini köklü biçimde değiştirdiği tarihten itibaren enflasyon serisinin hem ortalama düzeyinin hem de eğiminin kalıcı olarak farklılaşması hangi kavramla açıklanır?', 'Yapısal kırılma', ['Geçici aykırı gözlem', 'Mevsimsel kayma', 'Beyaz gürültü salınımı'], 'Yasal değişiklik, kriz veya teknolojik dönüşüm sonucu zaman serisi parametrelerinin kalıcı biçimde değişmesine yapısal kırılma denir.'),
  ('Dini bayramların miladi takvimde her yıl yaklaşık on bir gün öne kayması nedeniyle şekerleme ve giyim satışlarında farklı miladi aylarda görülen sıçramalar zaman serisi analizinde nasıl adlandırılır?', 'Hareketli tatil etkisi', ['Sabit çeyreklik mevsimsellik', 'Seküler büyüme trendi', 'Konjonktürel dip dalgası'], 'Hicri veya ay takvimine bağlı tatillerin miladi aylarda yer değiştirmesiyle oluşan özel takvim etkisine hareketli tatil (moving holiday) etkisi denir.'),
  ('Toplamsal bir zaman serisi modelinde mevsimsel etkilerin yılın tüm dönemleri boyunca net düzey değiştirmemesi için dört çeyreklik mevsimsel bileşenlerin (S1, S2, S3, S4) toplamı teorik olarak kaça eşit olmalıdır?', 'Sıfıra (0)', ['Bire (1)', 'Dörde (4)', 'Dört yüze (400)'], 'Toplamsal modelde mevsimsel sapmalar trend etrafında artı ve eksi yönlü dağılır; yıllık ortalamayı bozmaması için dönemlik etkilerin toplamı 0 olur.'),
  ('Çarpımsal bir ayrıştırma modelinde aylık bazda hesaplanan on iki mevsimsel endeks katsayısının (yüzdelik olmayan oran formunda) aritmetik ortalaması kaça eşit olacak biçimde normalize edilir?', '1,00 değerine', ['0,00 değerine', '12,0 değerine', '0,50 değerine'], 'Çarpımsal modelde oran biçimindeki 12 aylık mevsimsel çarpanların toplamı 12\'ye, dolayısıyla aritmetik ortalaması 1,00\'e (endeks formunda 100\'e) eşitlenir.'),
  ('İyi kurulmuş bir zaman serisi ayrıştırma modelinden geriye kalan düzensiz hata (artık) bileşeninin aşağıdaki özelliklerden hangisini taşıması beklenir?', 'Sıfır ortalamalı ve otokorelasyonsuz olması', ['Belirgin bir yıllık periyot sergilemesi', 'Zamanla doğrusal olarak büyümesi', 'Önceki dönem hatalarıyla güçlü bağ kurması'], 'Trend, mevsimsellik ve çevrim tam ayrıştırıldığında geriye kalan artık serisi sistematik örüntü içermeyen beyaz gürültü (sıfır ortalama, sabit varyans, ilişkisiz) olmalıdır.'),
  ('Doğrusal trend içeren durağan dışı bir seriyi Y_t yerine ΔY_t = Y_t - Y_{t-1} biçiminde ardışık dönem farklarını alarak durağanlaştırma işlemine ne ad verilir?', 'Birinci dereceden fark alma', ['Merkezli hareketli ortalama', 'Mevsimsel çarpanla bölme', 'Min-maks ölçeklendirme'], 'Ardışık gözlemler arasındaki farkın (Y_t - Y_{t-1}) hesaplanması birinci dereceden fark alma işlemidir ve doğrusal trendi ortadan kaldırır.'),
  ('Aylık doğalgaz tüketim verilerinde hem uzun dönemli artışı hem de her yıl aynı ayda tekrarlanan kış zirvesini tek adımda gidermek için Y_t - Y_{t-12} dönüşümü yapılmaktadır. Bu işlem hangisidir?', 'Mevsimsel fark alma', ['Üstel ağırlıklandırma', 'Karesel trend uydurma', 'Yatay kesit toplulaştırması'], 'Aylık veride her gözlemden 12 ay önceki (aynı takvim ayındaki) gözlemin çıkarılması mevsimsel fark alma işlemidir.'),
  ('Üç ayda bir yayımlanan çeyreklik ihracat serisinde çarpımsal model geçerlidir. İlk üç çeyreğin mevsimsel endeksleri sırasıyla 0,85, 0,95 ve 1,05 ise dördüncü çeyreğin mevsimsel endeksi kaç olmalıdır?', '1,15 katsayısı', ['1,05 katsayısı', '1,25 katsayısı', '0,90 katsayısı'], 'Dört çeyreklik çarpımsal endekslerin ortalaması 1 (toplamı 4,00) olmalıdır. İlk üçünün toplamı 0,85 + 0,95 + 1,05 = 2,85 olduğundan dördüncü çeyrek 4,00 - 2,85 = 1,15 olur.'),
  ('Yıllık toplamlar üzerinden derlenen (yılda tek bir gözlem içeren) buğday rekoltesi serisinde aşağıdaki zaman serisi bileşenlerinden hangisi tanım gereği gözlemlenemez?', 'Mevsimsel dalgalanma bileşeni', ['Uzun dönemli seküler trend', 'Konjonktürel çevrim hareketi', 'Kuraklık kaynaklı düzensiz şok'], 'Mevsimsellik yıl içi dönemler (ay, çeyrek, hafta) arasındaki düzenli hareketleri ölçtüğünden yıllık toplulaştırılmış verilerde mevsimsel bileşen ortadan kalkar.'),
  ('Güneş enerjisi santralinin saatlik elektrik üretim verisi incelendiğinde hem gece-gündüz döngüsü hem de yaz-kış döngüsü aynı anda görülmektedir. Bu tür serilerin temel özelliği nedir?', 'Çoklu mevsimsellik barındırması', ['Birim kök içermemesi', 'Yalnızca konjonktürel olması', 'Toplulaştırılmış kesit yapısında olması'], 'Yüksek frekanslı (saatlik, günlük) verilerde günlük, haftalık ve yıllık gibi birden fazla sabit periyotlu döngünün bir arada bulunmasına çoklu mevsimsellik denir.'),
  ('Çarpımsal modelle ayrıştırılan bir seride üçüncü çeyrek gerçek satış 396 ton, trend tahmini 360 ton ve mevsimsel endeks 1,10 olarak hesaplanmıştır. Konjonktür ve düzensiz bileşenlerin birleşik çarpımı (C × I) kaçtır?', '1,00 değeri', ['1,10 değeri', '0,90 değeri', '1,21 değeri'], 'Y = T × S × (C × I) formülünde 396 = 360 × 1,10 × (C × I) yazılır; 360 × 1,10 = 396 olduğundan C × I = 396 / 396 = 1,00 bulunur.'),
  ('Bir şehirdeki bisiklet kiralama verisinde tek bir günde ölçüm sensörünün bozulması yüzünden 0 kiralama kaydedilmiştir. Gerçekte faaliyet sürdüğü halde veri tabanına yansıyan bu tekil sapma nasıl ele alınmalıdır?', 'Toplamsal aykırı değer olarak düzeltilmelidir', ['Yeni bir mevsimsel dip olarak korunmalıdır', 'Uzun dönemli trendin sonu sayılmalıdır', 'Konjonktürel daralma başlangıcı kabul edilmelidir'], 'Kayıt veya sensör hatasından kaynaklanan tek dönemlik gerçek dışı gözlemler toplamsal aykırı değer (additive outlier) niteliğindedir ve tahmin öncesi onarılmalıdır.'),
  ('İki farklı durağan dışı zaman serisi (örneğin bir kasabadaki leylek yuvası sayısı ile dünyanın başka ucundaki kripto madencilik hacmi) aynı yönde trend taşıdığı için aralarında çok yüksek korelasyon çıkması hangi yanılgıya örnektir?', 'Sahte (düzmece) ilişki', ['Mevsimsel eşbütünleşme', 'Takvim kayması hatası', 'Örneklem seçilim yanlılığı'], 'Aralarında nedensel bağ bulunmayan iki serinin yalnızca ortak zaman trendi yüzünden yüksek korelasyon göstermesi sahte (spurious) regresyon/ilişki olarak adlandırılır.'),
  ('Üstel trend denklemi T_t = 200 × (1,05)^t olan bir bulut depolama şirketinin veri trafiği (TB cinsinden) t = 0 başlangıç döneminden t = 2 dönemine geldiğinde trend bazında kaç TB artmış olur?', '20,5 TB artış', ['20,0 TB artış', '10,5 TB artış', '21,0 TB artış'], 't = 0 için T_0 = 200 TB, t = 2 için T_2 = 200 × (1,05)² = 200 × 1,1025 = 220,5 TB olur. Artış miktarı 220,5 - 200 = 20,5 TB\'dir.'),
  ('Bir zaman serisi grafiğinde gözlemler yatay eksene paralel bir bant içinde salınıyor ancak zaman ilerledikçe bu bandın alt ve üst sınırları huni biçiminde genişliyorsa serinin hangi varsayımı ihlal edilmektedir?', 'Varyansın zaman boyunca sabitliği', ['Ortalama düzeyin sabit kalması', 'Gözlemlerin eşit aralıklı toplanması', 'Trend eğiminin sıfır olması'], 'Ortalama sabit kalsa bile dalgalanma genliğinin (yayılımın) zamanla büyümesi sabit varyans (homoskedastisite) koşulunun bozulduğunu ve serinin durağan olmadığını gösterir.'),
  ('Bir havaalanının aylık yolcu sayıları toplamsal modelle ayrıştırılmıştır. Ocak ayı gerçek yolcu sayısı 620 bin, mevsimsel etki -90 bin ve birleşik konjonktür-hata terimi (C + I) +10 bin kişi ise ocak ayı trend değeri kaç bin kişidir?', '700 bin kişi', ['540 bin kişi', '720 bin kişi', '680 bin kişi'], 'Y = T + S + (C + I) eşitliğinde 620 = T - 90 + 10 = T - 80 olur; buradan T = 620 + 80 = 700 bin kişi hesaplanır.'),
  ('Çarpımsal bir seride düzensiz şok dışındaki sistematik kısım T × S × C çarpımıyla tahmin edilmektedir. Gerçek gözlem 264 birim, trend 250 birim, mevsimsel çarpan 0,80 ve konjonktürel çarpan 1,20 ise düzensiz bileşen (I) kaçtır?', '1,10 çarpanı', ['1,05 çarpanı', '0,95 çarpanı', '1,24 çarpanı'], 'Sistematik çarpım 250 × 0,80 × 1,20 = 200 × 1,20 = 240 birimdir. Düzensiz çarpan I = Y / (T × S × C) = 264 / 240 = 1,10 olarak bulunur.'),
  ('Klasik zaman serisi ayrıştırmasında trend ve konjonktür bileşenlerinin kısa örneklem dönemlerinde birbirinden ayırt edilmesi güç olduğunda araştırmacılar genellikle nasıl bir birleştirme yoluna gider?', 'Trend-konjonktür bileşeni olarak tek kalemde tahmin ederler', ['Konjonktürü mevsimsel bileşenin içine dahil ederler', 'Trendi tamamen silip seriyi sıfır ortalamalı kabul ederler', 'Düzensiz hata terimini trendle çarparak sabitlerler'], 'Özellikle gözlem süresinin birkaç iş çevrimini kapsamadığı serilerde uzun dönemli eğilim ve çevrim birleştirilerek pürüzsüz \'trend-konjonktür\' eğrisi olarak tahmin edilir.'),
  ('Yedi yıllık bir seride simetrik zaman kodlaması (-3, -2, -1, 0, 1, 2, 3) kullanılarak T_t = b_0 + b_1 t doğrusal trendi tahmin edilmiştir. Yedi yılın gözlem toplamı ΣY = 630 birim ise doğrusal trendin kesme noktası (b_0) kaçtır?', '90 birim', ['105 birim', '70 birim', '85 birim'], 'Σt = 0 olduğu için sabit terim b_0 doğrudan gözlemlerin aritmetik ortalamasına eşittir: b_0 = ΣY / n = 630 / 7 = 90 birim.'),
  ('Stok değişkeni ve akım değişkeni ayrımı zaman serilerinin toplulaştırılmasında kritik önem taşır. Aşağıdaki serilerden hangisi aylık veriden yıllık veriye dönüştürülürken on iki ayın toplamı alınarak değil, dönem sonu veya ortalaması alınarak raporlanmalıdır?', 'Baraj göllerindeki su doluluk hacmi', ['Fabrikada üretilen toplam çimento tonajı', 'Gişelerden geçen ücretli araç sayısı', 'Belediyenin tahsil ettiği su faturası geliri'], 'Barajdaki su miktarı belirli bir andaki birikimi gösteren stok değişkenidir; on iki ayın doluluklarını toplamak anlamsızdır, üretim ve geçiş sayıları ise akım değişkenidir.'),
  ('Bir ülkenin çeyreklik işsizlik oranı serisi ile yıllık kurulan yeni şirket sayısı serisi karşılaştırıldığında, toplulaştırma kuralı bakımından hangisi doğrudur?', 'İşsizlik oranı ortalaması alınarak, şirket sayısı toplanarak yıllığa çevrilir', ['Her iki seri de dört çeyrek üst üste toplanarak yıllığa çevrilir', 'İşsizlik oranı toplanarak, şirket sayısı son çeyrek seçilerek raporlanır', 'Oran ve sayım serilerinin frekansı hiçbir koşulda değiştirilemez'], 'Oran/yüzde niteliğindeki göstergeler dönemler boyunca toplanamaz (ağırlıklı veya basit ortalaması alınır); yeni kurulan şirket sayısı ise akım değişkeni olduğundan toplanır.'),
  ('Bir zaman serisinde sinyal-gürültü oranı (signal-to-noise ratio) çok düşükse seri grafiğinde nasıl bir görünüm hakim olur?', 'Rastlantısal zikzaklar alttaki trend ve mevsimsel örüntüyü gölgeler', ['Gözlemler kusursuz bir doğru çizgi üzerinde hiç sapmadan dizilir', 'Mevsimsel zirveler her yıl tam olarak aynı sayısal değerde gerçekleşir', 'Artık hata terimlerinin varyansı sıfıra çok yakın çıkar'], 'Sinyal (trend + mevsimsellik) zayıf, gürültü (düzensiz bileşen varyansı) yüksek olduğunda seri çok dalgalı görünür ve sistematik yapıyı seçmek güçleşir.'),
  ('Bir limana yanaşan konteyner gemisi sayısının aylık serisinde pandemi başlangıcındaki kapanma kararıyla nisan ayından itibaren tüm ayların ortalaması kalıcı biçimde 400 gemiden 280 gemiye inmiştir. Bu durum hangisine örnektir?', 'Kalıcı düzey kayması', ['Tek dönemlik ölçüm hatası', 'Düzenli mevsimsel dalgalanma', 'Takvim günü farklılığı'], 'Belirli bir tarihten sonra serinin ortalama seviyesinin aniden başka bir platoya oturup orada devam etmesi kalıcı düzey kayması olarak tanımlanır.'),
  ('Bir perakende giyim markasının haftalık satış verilerinde kasım ayının son haftasındaki indirim kampanyası günlerinde her yıl tekrarlanan olağanüstü satış sıçraması hangi bileşen içinde modellenmelidir?', 'Yıllık tekrarlanan özel mevsimsel/takvim etkisi', ['Öngörülemeyen düzensiz doğal afet şoku', 'Yirmi yıllık seküler nüfus eğilimi', 'Beş yıllık makroekonomik konjonktür'], 'Her yıl aynı dönemde düzenli olarak uygulanan kampanya günleri öngörülebilir ve periyodik olduğundan mevsimsel/takvim bileşeni kapsamında modellenir.'),
  ('Zaman serisi tahmininde modelin geçmiş veriye aşırı uyum sağlaması (overfitting) durumunda rastlantısal düzensiz bileşene ne olur?', 'Gürültü gerçek bir örüntü sanılarak modele dahil edilir ve gelecek tahminleri bozulur', ['Düzensiz bileşen tamamen doğru öngörülerek gelecekteki şoklar sıfırlanır', 'Model yalnızca uzun dönemli ortalamayı tahmin edip tüm dalgaları yok sayar', 'Örneklem dışı tahmin hatası örneklem içi hatadan çok daha küçük çıkar'], 'Çok fazla parametre içeren aşırı uyumlu modeller geçmişteki tekil rastlantısal şokları ezberler; bu şoklar tekrarlanmayacağı için örneklem dışı öngörü başarısı düşer.'),
  ('Bir zaman serisinin örneklem içi (in-sample) uyumu ile örneklem dışı (out-of-sample) tahmin performansını sınamak isteyen bir analist veriyi nasıl bölmelidir?', 'Kronolojik sırayı bozmadan son dönemleri test kümesi olarak ayırmalıdır', ['Tüm yıllardan rastgele kura çekerek %20 test örneklemi seçmelidir', 'Yalnızca en yüksek satışlı ayları eğitim kümesine toplamalıdır', 'Tek sayılı ayları eğitim, çift sayılı ayları doğrulama kümesi yapmalıdır'], 'Zaman serilerinde gelecek geçmişten tahmin edildiği ve zamansal bağımlılık bulunduğu için rastgele bölme veri sızıntısı yaratır; kronolojik kesim zorunludur.'),
  ('Toplamsal ayrıştırma modelinde bir mağazanın dört çeyreklik trend değerleri sırasıyla 100, 110, 120 ve 130 birim; çeyreklik mevsimsel etkileri ise -20, -5, +10 ve +15 birimdir. Rastlantısal ve konjonktürel etkinin sıfır olduğu varsayılırsa yıllık toplam satış kaç birim olur?', '460 birim', ['485 birim', '440 birim', '465 birim'], 'Mevsimsel etkilerin toplamı (-20 - 5 + 10 + 15 = 0) birbirini götürür; yıllık toplam doğrudan dört çeyreklik trendin toplamına (100 + 110 + 120 + 130 = 460) eşittir.'),
  ('Bir dondurulmuş gıda firmasının çeyreklik satışları çarpımsal modelde T_t = 500 + 25t (t = 1\'den başlayan çeyrek sırası) ve mevsimsel endeksler S_1 = 0,80, S_2 = 1,00, S_3 = 1,30, S_4 = 0,90 olarak belirlenmiştir. Modelin t = 6. çeyrek (2. yılın 2. çeyreği) için nokta tahmini kaç birimdir?', '650 birim', ['845 birim', '520 birim', '625 birim'], 't = 6 için trend T_6 = 500 + 25 × 6 = 650 birimdir. 6. çeyrek ikinci yılın 2. çeyreğine denk geldiğinden S_2 = 1,00 ile çarpılır: 650 × 1,00 = 650 birim.'),
  ('Aynı modelde (T_t = 500 + 25t; S_1 = 0,80, S_2 = 1,00, S_3 = 1,30, S_4 = 0,90) t = 7. çeyrek (2. yılın 3. çeyreği) için beklenen satış tahmini kaç birimdir?', '877,5 birim', ['675,0 birim', '780,0 birim', '812,5 birim'], 't = 7 için T_7 = 500 + 25 × 7 = 675 birimdir. 3. çeyrek mevsimsel çarpanı S_3 = 1,30 olduğundan tahmin 675 × 1,30 = 877,5 birim olur.'),
  ('Zaman serisi grafiklerinde düşey eksenin aritmetik ölçek yerine yarı-logaritmik (oran) ölçekle çizilmesinin analiste sağladığı en önemli görsel avantaj nedir?', 'Sabit yüzdelik hızla büyüyen bir seriyi düz bir doğru olarak göstermesi', ['Negatif ve sıfır değerleri grafikte daha belirgin hale getirmesi', 'Mevsimsel dalgalanmaları hiçbir işlem yapmadan silmesi', 'Rastlantısal aykırı değerleri tam ortalamaya çekmesi'], 'Yarı-logaritmik grafikte yatay eksen zamanı doğrusal, düşey eksen logaritmayı gösterir; böylece sabit oransal (üstel) büyüme doğrusal bir çizgi olarak görünür.'),
  ('Elektrik tüketimi yirmi yıl önce yalnızca kışın ısınma kaynaklı zirve yaparken, klima kullanımının yaygınlaşmasıyla son on yılda ağustos ayında ikinci bir zirve oluşturmaya başlamıştır. Bu olgu zaman serilerinde neyi ifade eder?', 'Evrilen (değişken) mevsimsellik yapısını', ['Serinin tamamen beyaz gürültüye dönüştüğünü', 'Uzun dönemli trendin sıfırlandığını', 'Takvim günlerinin kısaldığını'], 'Teknolojik veya davranışsal dönüşümler sonucunda yıl içi mevsimsel profilin şekil değiştirmesine evrilen/hareketli mevsimsellik denir.'),
  ('Bir zaman serisi Y_t\'nin otokovaryans fonksiyonu γ(k), t ve t-k dönemleri arasındaki ortak değişimi ölçer. k = 0 gecikmesi için hesaplanan γ(0) değeri istatistiksel olarak neye eşittir?', 'Serinin kendi varyansına', ['Serinin aritmetik ortalamasına', 'Birinci derece otokorelasyona', 'Standart sapmanın kareköküne'], 'Sıfır gecikmede Cov(Y_t, Y_t) = Var(Y_t) olduğundan γ(0) doğrudan serinin varyansını verir.'),
  ('Bir şehrin günlük hava sıcaklığı serisinde düzensiz şok (örneğin ani soğuk cephe geçişi) yaşandığında ertesi günkü sıcaklığın da bundan kısmen etkilendiği, ancak etkinin birkaç gün içinde sönümlenip mevsim normallerine döndüğü görülüyor. Bu özellik hangisini gösterir?', 'Şokların geçici etki bıraktığı ortalamaya/trende dönüş özelliğini', ['Birim köklü kalıcı düzey kayması yaşandığını', 'Sıcaklık serisinin hiçbir mevsimsellik içermediğini', 'Ardışık günler arasında hiçbir bağımlılık bulunmadığını'], 'Durağan (veya mevsimsel-trend durağan) süreçlerde rastlantısal şokların etkisi zamanla azalır (bellek sönümlenir) ve seri kendi beklenen yörüngesine döner.'),
  ('Güçlü mevsimsellik gösteren bir dondurma satış serisinde temmuz ayı verisi kaybolmuştur. Haziran ve ağustos ortalaması yerine geçen yılların temmuz/yıllık oranını da dikkate alarak atama yapılmasının temel gerekçesi nedir?', 'Mevsimsel zirve noktasının komşu ayların ortalamasıyla olduğundan düşük tahmin edilmesini önlemek', ['Verideki gözlem sayısını on iki aydan on bir aya düşürmek', 'Uzun dönemli trendi tamamen negatif yöne çevirmek', 'Standart sapmayı sıfıra eşitleyip seriyi sabit hale getirmek'], 'Temmuz keskin bir zirve (peak) ise haziran ve ağustos ortalaması zirveyi tıraşlayarak aşağı yanlı atama yapar; mevsimsel yapı korunarak tamamlama yapılmalıdır.'),
  ('Zaman serisi tahmin hatalarını ölçmekte kullanılan Ortalama Mutlak Hata (MAE) ile Kök Ortalama Kare Hata (RMSE) karşılaştırıldığında RMSE ölçütünün ayırt edici özelliği nedir?', 'Kare alma işlemi nedeniyle büyük tekil tahmin hatalarını daha ağır cezalandırması', ['Birimden bağımsız yüzdelik bir oran olarak raporlanması', 'Pozitif ve negatif hataların birbirini götürmesine izin vermesi', 'Her koşulda ortalama mutlak hatadan daha küçük bir sayı çıkması'], 'RMSE hataların karelerinin ortalamasının karekökünü aldığından, büyük sapmalara (aykırı hatalara) MAE\'ye kıyasla çok daha yüksek ağırlık verir.'),
  ('Dört ardışık dönemde bir modelin gerçekleşen değerleri (Y) sırasıyla 100, 120, 90, 110; tahmin değerleri (Ŷ) ise 96, 125, 93, 104 olmuştur. Bu dört dönem için Ortalama Mutlak Hata (MAE) kaç birimdir?', '4,5 birim', ['1,0 birim', '5,0 birim', '3,5 birim'], 'Mutlak hatalar |100 - 96| = 4, |120 - 125| = 5, |90 - 93| = 3 ve |110 - 104| = 6 birimdir. Toplamları 4 + 5 + 3 + 6 = 18; ortalaması 18 / 4 = 4,5 birimdir.'),
  ('Üç dönemlik tahmin hataları (e_t = Y_t - Ŷ_t) sırasıyla +3, -6 ve +6 birim olarak hesaplanmıştır. Bu tahmin modelinin Kök Ortalama Kare Hatası (RMSE) kaç birimdir?', '5,196 (yaklaşık 5,2) birim', ['5,000 birim', '1,000 birim', '9,000 birim'], 'Hata kareleri 9, 36 ve 36\'dır; toplamı 81, ortalaması (MSE) 81 / 3 = 27 olur. Karekökü √27 ≈ 5,196 birimdir.'),
  ('Ortalama Mutlak Yüzde Hata (MAPE) ölçütü farklı ölçekteki serilerin (örneğin TL bazlı ciro ile adet bazlı satışın) tahmin başarısını kıyaslamada çok kullanışlıdır; ancak hangi durumda tanımsızlaşır veya aşırı çarpık sonuç verir?', 'Gerçekleşen gözlem değerlerinin sıfır veya sıfıra çok yakın olduğu dönemlerde', ['Serinin tüm değerlerinin pozitif ve yüzün üzerinde olduğu durumlarda', 'Örneklem döneminin yirmi dört aydan uzun seçildiği analizlerde', 'Tahmin değerlerinin gerçekleşen değerlere çok yakın çıktığı serilerde'], 'MAPE formülünde |Y_t - Ŷ_t| / |Y_t| yer aldığından paydadaki gerçek değer Y_t = 0 olduğunda sıfıra bölme hatası oluşur, sıfıra çok yakınken hata yüzdesi patlar.'),
  ('Bir tahmin modelinin hataları toplanıp dönem sayısına bölündüğünde (Ortalama Hata, ME = Σ(Y_t - Ŷ_t)/n) sonucun belirgin biçimde pozitif (+18 birim gibi) çıkması model hakkında neyi gösterir?', 'Modelin sistematik olarak gerçekleşen değerlerin altında (eksik) tahmin ürettiğini', ['Modelin gerçekleşen değerlerin sürekli üzerinde (fazla) tahmin yaptığını', 'Tahmin hatalarının varyansının sıfıra eşit olduğunu', 'Modelin hiçbir yanlılık taşımadan tam isabet sağladığını'], 'Y_t - Ŷ_t farklarının ortalaması pozitifse Y_t genel olarak Ŷ_t\'den büyüktür; yani model gerçek değerleri sistematik biçimde düşük (underforecast) tahmin etmektedir.'),
  ('Log-doğrusal trend modeli ln(Y_t) = 4,60 + 0,03t olarak tahmin edilen bir yazılım şirketinin abone sayısında 0,03 eğim katsayısının yaklaşık ekonomik yorumu hangisidir?', 'Abone sayısının her dönem yaklaşık %3 oranında büyüdüğü', ['Abone sayısının her dönem sabit 0,03 kişi arttığı', 'Toplam abone sayısının 4,60 milyonla sınırlı kaldığı', 'Mevsimsel sapmanın %30 düzeyinde gerçekleştiği'], 'Bağımlı değişken doğal logaritma, açıklayıcı değişken doğrusal zaman olduğunda (yarı-esneklik modeli), küçük β_1 değerleri için 100 × β_1 yaklaşık dönemlik yüzdesel büyümeyi verir.'),
  ('Bir veri analisti aylık konut kredisi faiz serisini çeyreklik GSYH büyümesiyle aynı modelde ilişkilendirmek istemektedir. İki serinin gözlem sıklığı (frekansı) farklı olduğunda standart toplulaştırma yaklaşımı nasıldır?', 'Yüksek frekanslı aylık faiz serisinin üçer aylık ortalamaları alınarak çeyreklik frekansa indirgenir', ['Çeyreklik GSYH rakamı üçe çarpılarak her aya aynı büyüme oranı yazılır', 'Aylık serinin yalnızca ocak, şubat ve mart ayları seçilip kalan dokuz ay silinir', 'İki serinin gözlemleri tarihlerine bakılmaksızın alt alta birleştirilir'], 'Farklı frekanslı seriler ortak modele alınırken genellikle yüksek frekanslı seri (stok/oran ise ortalamayla, akım ise toplamla) düşük frekansa dönüştürülür.'),
  ('Uzun dönemli bir zaman serisinde tahmin ufku (h adım sonrası) uzadıkça nokta tahminin etrafındaki %95 öngörü aralığının (prediction interval) genişliği durağan dışı serilerde nasıl davranır?', 'Tahmin ufku ilerledikçe belirsizlik biriktiği için aralık sürekli genişler', ['Gelecekteki şoklar birbirini yok ettiği için aralık sıfıra daralır', 'Kaç dönem ileri gidilirse gidilsin aralık genişliği sabit kalır', 'Öngörü aralığı yalnızca kış aylarında daralıp yazın sabitlenir'], 'Özellikle trend veya birim kök içeren serilerde adım sayısı h arttıkça hata varyansı birikir ve öngörü güven bandı huni şeklinde açılır.'),
  ('Yedi ardışık günün kargo teslimat sayıları sırasıyla 120, 135, 125, 140, 160, 150 ve 170 pakettir. Üç günlük simetrik basit hareketli ortalama uygulandığında 4. gün (140 paketlik gün) için yumuşatılmış değer kaç olur?', '141,67 paket', ['133,33 paket', '150,00 paket', '140,00 paket'], 'Simetrik 3 günlük hareketli ortalamada 4. günün değeri 3., 4. ve 5. günlerin ortalamasıdır: (125 + 140 + 160) / 3 = 425 / 3 ≈ 141,67 paket.'),
  ('Çeyreklik (dört dönemlik) bir zaman serisinde dört dönemlik hareketli ortalama alındığında elde edilen ortalamanın tam bir çeyrek döneme denk gelmeyip iki çeyrek arasına (örneğin 2,5. döneme) düşmesi sorunu nasıl çözülür?', 'Ardışık iki dörtlü hareketli ortalamanın tekrar iki dönemlik ortalaması alınarak merkezlendirilir', ['Dört çeyrek yerine üç çeyreklik ortalama alınarak mevsimsellik göz ardı edilir', 'Hesaplanan ortalama değeri doğrudan bir sonraki yılın ilk çeyreğine yazılır', 'Yalnızca ilk ve son çeyreklerin geometrik ortalaması alınarak ara dönemler silinir'], 'Çift dönemli (k = 4 veya k = 12) hareketli ortalamalarda zaman indisini tam döneme oturtmak için 2×4 (veya aylıkta 2×12) merkezli hareketli ortalama uygulanır.'),
  ('Belirgin ve sürekli pozitif doğrusal trend içeren bir zaman serisinde geriye dönük basit hareketli ortalama (Y_{t-1}, Y_{t-2}, ..., Y_{t-k} ortalaması) bir sonraki dönemin tahmini olarak kullanıldığında nasıl bir sistematik hata oluşur?', 'Tahminler gerçekleşen trend değerlerinin sürekli altında (gerisinde) kalır', ['Tahminler gerçekleşen değerlerin sürekli iki katı üzerinde seyreder', 'Hata ortalaması sıfır olur ve hiçbir sistematik gecikme görülmez', 'Yalnızca tek sayılı dönemlerde fazla, çift sayılı dönemlerde eksik tahmin üretir'], 'Yukarı eğimli bir seride geçmiş k dönemin ortalaması mevcut düzeyden daha düşük olacağı için basit hareketli ortalama trendi gecikmeli izler ve sistematik eksik tahmin yapar.'),
  ('Basit üstel düzleştirme formülü F_{t+1} = α Y_t + (1 - α) F_t (0 < α < 1) geçmiş gözlemler cinsinden sonsuz seri olarak açıldığında geçmiş dönemlere verilen ağırlıklar nasıl bir yapı sergiler?', 'Geçmişe doğru gidildikçe geometrik (üstel) olarak azalan pozitif ağırlıklar alır', ['Geçmişe doğru gidildikçe aritmetik dizi biçiminde doğrusal olarak artar', 'İlk beş dönem eşit ağırlık alır, daha eski dönemlerin ağırlığı tam sıfır olur', 'Tek dönem gecikmelere pozitif, çift dönem gecikmelere negatif ağırlık verilir'], 'Açılımda Y_t\'nin katsayısı α, Y_{t-1}\'in α(1-α), Y_{t-2}\'nin α(1-α)² şeklinde azaldığından yöntem \'üstel düzleştirme\' adını alır ve ağırlıklar toplamı 1\'e yakınsar.'),
  ('Basit üstel düzleştirmede düzleştirme parametresi α değeri 1\'e çok yakın (örneğin 0,95) seçildiğinde modelin davranışı aşağıdakilerden hangisine yaklaşır?', 'Son gözlemi neredeyse aynen kopyalayan naif tahmin yöntemine', ['Tüm geçmiş verilerin eşit ağırlıklı genel aritmetik ortalamasına', 'Yirmi dönemlik çok pürüzsüz merkezli hareketli ortalamaya', 'Sabit eğimli en küçük kareler doğrusal regresyon doğrusuna'], 'α = 1 sınır değerinde F_{t+1} = Y_t olur; dolayısıyla α bire yaklaştıkça geçmiş tahminlerin hafızası silinir ve model naif yönteme dönüşür.'),
  ('Holt doğrusal üstel düzleştirme modelinde t dönemi sonunda güncellenmiş düzey L_t = 250 birim ve güncellenmiş eğim (trend) T_t = 12 birim olarak hesaplanmıştır. Bu modelin 4 dönem sonrası (t + 4) için nokta öngörüsü kaç birimdir?', '298 birim', ['262 birim', '310 birim', '286 birim'], 'Holt yönteminde h adım sonrası öngörü F_{t+h} = L_t + h × T_t formülüyle bulunur: 250 + 4 × 12 = 250 + 48 = 298 birim.'),
  ('Klasik çarpımsal ayrıştırmada \'hareketli ortalamaya oran\' (ratio-to-moving-average) yöntemi uygulanırken gözlenen değer Y_t, merkezli hareketli ortalama değeri MA_t\'ye bölündüğünde (Y_t / MA_t) yaklaşık olarak hangi bileşenler elde edilir?', 'Mevsimsel ve düzensiz bileşenlerin çarpımı (S × I)', ['Trend ve konjonktürel bileşenlerin çarpımı (T × C)', 'Yalnızca uzun dönemli deterministik trend bileşeni (T)', 'Konjonktürel ve düzensiz bileşenlerin toplamı (C + I)'], 'Merkezli hareketli ortalama MA_t yaklaşık olarak T × C eğrisini temsil ettiğinden, Y_t / MA_t = (T × S × C × I) / (T × C) = S × I oranını verir.'),
  ('Hareketli ortalamaya oran yönteminde her takvim ayı için yıllar boyunca hesaplanan S × I oranlarından düzensiz (I) bileşeni ve uç aykırı şokları temizleyerek ham mevsimsel endeksi bulmak için uygulamada sıklıkla hangi ortalama tercih edilir?', 'En büyük ve en küçük uç değerler atıldıktan sonra kalanların ortalaması (kırpılmış/değiştirilmiş ortalama)', ['Yalnızca en yüksek ve en düşük iki yılın aritmetik ortalaması (orta aralık değeri)', 'Tüm yılların oranlarının birbirleriyle çarpımından oluşan kümülatif toplam', 'Yalnızca serinin ilk yılındaki tekil oranın diğer yıllara kopyalanması'], 'Belirli bir ayda tek bir yılda yaşanmış grev veya afet şokunun mevsimsel endeksi çarpıtmaması için medyan veya uçları kırpılmış (modified/trimmed) aritmetik ortalama kullanılır.'),
  ('Mevsim etkisinden arındırılmış bir seride yeni bir ayın verisi açıklandığında geçmiş aylara ait daha önce yayımlanmış mevsimden arındırılmış değerlerin küçük miktarlarda değişmesi olgusuna ne ad verilir?', 'Mevsimsel düzeltme revizyonu', ['Baz yılı kaydırma hatası', 'Sahte regresyon kırılması', 'İkame yanlılığı sapması'], 'Yeni gözlemler eklendikçe uç dönemlerdeki asimetrik filtrelerin yerini daha simetrik filtreler alır ve model parametreleri güncellenir; bu doğal güncellemeye revizyon denir.'),
  ('Mevsim etkisinden arındırılmış bir zaman serisinin içinde aşağıdaki bileşenlerden hangileri hala varlığını sürdürür?', 'Uzun dönemli trend, konjonktürel çevrim ve düzensiz (rastlantısal) bileşen', ['Yalnızca takvim günü etkileri ve sabit mevsimsel dalgalanmalar', 'Yalnızca deterministik doğrusal trend, diğer tüm bileşenler silinmiştir', 'Mevsimsel bileşen ve hareketli tatil etkilerinin ağırlıklı toplamı'], 'Mevsimsel düzeltme (Y / S veya Y - S) yalnızca mevsimsel (ve uygulanmışsa takvim) bileşenini çıkarır; geriye trend, konjonktür ve düzensiz şoklar (T, C ve I) kalır.'),
  ('Bir malın 2018 = 100 sabit esaslı fiyat endeksi 2019\'da 120, 2020\'de 150 ve 2021\'de 180 olarak gerçekleşmiştir. Bu malın 2020 yılı için zincirleme (bir önceki yıla göre, 2019 = 100) fiyat endeksi kaçtır?', '125,0 endeks puanı', ['130,0 endeks puanı', '150,0 endeks puanı', '120,0 endeks puanı'], 'Sabit esaslı tekil endekslerde zincirleme halka I_{2020/2019} = (150 / 120) × 100 = 1,25 × 100 = 125,0 olur.'),
  ('Bir zeytinyağı markasının bir önceki yıla göre hesaplanan zincirleme fiyat halkaları üç ardışık yılda sırasıyla 110, 120 ve 125 olarak bulunmuştur. Başlangıç yılı (t = 0) 100 kabul edilirse üçüncü yılın sonundaki sabit esaslı fiyat endeksi kaç olur?', '165,0 endeks puanı', ['155,0 endeks puanı', '118,3 endeks puanı', '355,0 endeks puanı'], 'Zincirleme halkaların çarpımı sabit esaslı endeksi verir: 100 × (1,10) × (1,20) × (1,25) = 100 × 1,32 × 1,25 = 165,0.'),
  ('Tek bir ürünün fiyatı baz döneme göre %20 artarken (fiyat endeksi 120), satış miktarı baz döneme göre %10 azalmıştır (miktar endeksi 90). Bu ürünün baz döneme göre basit değer (ciro) endeksi kaçtır?', '108,0 endeks puanı', ['110,0 endeks puanı', '105,0 endeks puanı', '112,0 endeks puanı'], 'Değer = Fiyat × Miktar olduğundan basit değer endeksi V_{0t} = (P_t Q_t / P_0 Q_0) × 100 = (1,20 × 0,90) × 100 = 108,0 olarak bulunur.'),
  ('Bir istatistik kurumu 2015 yılında sepet yapısını yenileyerek eski endeksi (2005 = 100) durdurmuş ve 2015 = 100 bazlı yeni endeksi başlatmıştır. 2015 yılında eski endeks 220, yeni endeks 100 iken; 2018 yılında yeni endeks 140 olmuştur. İki seriyi birleştirerek (splicing) 2005 = 100 bazında devam ettirmek isteyen bir analist 2018 değerini kaç bulur?', '308,0 endeks puanı', ['260,0 endeks puanı', '360,0 endeks puanı', '284,0 endeks puanı'], 'Ortak örtüşme yılı olan 2015\'te bağlama katsayısı 220 / 100 = 2,20\'dir. 2018 yeni endeksi bu katsayıyla çarpılır: 140 × 2,20 = 308,0.'),
  ('Aynı ortak yılda örtüşen eski ve yeni iki endeks serisi geriye doğru (yeni baz yılı esas alınarak eski yılların yeniden ölçeklenmesi biçiminde) birleştirildiğinde 2015 yılında eski endeks 200, yeni endeks 100 ve 2012 yılında eski endeks 150 ise 2012 yılının yeni baza (2015 = 100) çevrilmiş değeri kaçtır?', '75,0 endeks puanı', ['50,0 endeks puanı', '125,0 endeks puanı', '80,0 endeks puanı'], 'Eski seri 2015 yılındaki eski endeks değerine bölünüp 100 ile çarpılır: (150 / 200) × 100 = 75,0.'),
  ('Birden fazla mal içeren ağırlıksız bir endeks hesaplanırken mal fiyatlarının doğrudan toplanıp baz yıl fiyat toplamına bölünmesiyle (ΣP_t / ΣP_0 × 100) bulunan \'basit toplamsal (agregatif) fiyat endeksinin\' en ciddi metodolojik kusuru nedir?', 'Malların ölçü birimlerine (ton, kilogram, gram gibi) bağımlı olması ve pahalı birimli malın endeksi tek başına domine etmesi', ['Baz yılı ile cari yıl fiyatları eşit olduğunda 100 yerine sıfır sonucu üretmesi', 'Yalnızca logaritmik ölçekte hesaplanabildiği için toplama işlemine izin vermemesi', 'Tüketim miktarlarını iki kez çarparak hiperenflasyon yanılsaması yaratması'], 'Basit toplamsal endekste örneğin sütün litresi yerine tonu, altının kilogramı yerine gramı yazıldığında endeks değeri tamamen değişir (birim değişmezliği / commensurability testini geçemez).'),
  ('Irving Fisher\'ın endeks sayıları için tanımladığı aksiyomatik testlerden \'Zaman Tersinirliği Testi\' (Time Reversal Test) hangi matematiksel koşulun sağlanmasını şart koşar?', '0 bazlı t dönemi endeksi ile t bazlı 0 dönemi endeksinin çarpımının (oran formunda) 1\'e eşit olmasını', ['Fiyat endeksi ile miktar endeksinin toplamının değer endeksinin iki katına eşit olmasını', 'Herhangi bir t döneminde tüm fiyatlar iki katına çıktığında endeksin değişmemesini', 'Aritmetik ortalama endeksinin her zaman harmonik ortalama endeksine eşit çıkmasını'], 'Zaman yönü ters çevrildiğinde (baz ve cari dönem yer değiştirdiğinde) yeni endeks eski endeksin çarpmaya göre tersi (1 / I_{0t}) olmalıdır.'),
  ('İki maldan oluşan ağırlıksız Carli (fiyat rölatiflerinin aritmetik ortalaması) endeksinde A malının fiyatı iki katına çıkarken (P_1/P_0 = 2), B malının fiyatı yarıya düşmüştür (P_1/P_0 = 0,5). Geometrik (Jevons) endeks 100 gösterirken Carli endeksi kaç gösterir?', '125,0 endeks puanı', ['100,0 endeks puanı', '80,0 endeks puanı', '150,0 endeks puanı'], 'Aritmetik ortalama [(2,0 + 0,5) / 2] × 100 = 1,25 × 100 = 125,0 verir; oysa geometrik ortalama √(2 × 0,5) × 100 = 100 vererek simetrik değişimi doğru yansıtır.'),
  ('Endeks teorisinde \'Faktör Tersinirliği Testi\' (Factor Reversal Test) bir endeks formülünün hangi eşitliği sağlamasını gerektirir?', 'Aynı formülle hesaplanan fiyat endeksi ile miktar endeksinin çarpımının toplam değer (harcama) oranına (ΣP_t Q_t / ΣP_0 Q_0) eşit olmasını', ['0 döneminden 1 dönemine ve 1 döneminden 2 dönemine endeks çarpımının doğrudan 0-2 endeksine eşit olmasını', 'Malların ölçü birimleri kilogramdan tona çevrildiğinde endeks değerinin aynı oranda küçülmesini', 'Sepete yeni bir mal eklendiğinde geçmiş yılların tüm endeks sayılarının sabit kalmasını'], 'Tek bir malda P × Q = V olduğu gibi, toplulaştırılmış endekslerde de P_{0t} × Q_{0t} = V_{0t} = Σ(P_t Q_t) / Σ(P_0 Q_0) koşulunu arayan test faktör tersinirliği testidir.'),
  ('0 döneminden 1 dönemine endeks I_{01} ve 1 döneminden 2 dönemine endeks I_{12} iken, I_{01} × I_{12} = I_{02} eşitliğinin her türlü fiyat-miktar verisinde sağlanmasını arayan aksiyomatik özellik hangisidir?', 'Dairesellik (geçişlilik / circularity) testi', ['Orantılılık (proportionality) testi', 'Birim değişmezliği (commensurability) testi', 'Monotonluk (monotonicity) testi'], 'Zincirleme çarpımın doğrudan sabit bazlı endekse eşit olmasını (dolayısıyla baz yılı seçiminin oransal karşılaştırmaları değiştirmemesini) talep eden özellik dairesellik testidir.'),
  ('Ağırlıksız rölatif ortalamaları olan Carli (aritmetik), Jevons (geometrik) ve Coggeshall (harmonik) fiyat endeksleri, sepetteki malların fiyat artış oranları birbirinden farklı olduğunda büyüklük açısından nasıl sıralanır?', 'Harmonik endeks < Geometrik endeks < Aritmetik endeks', ['Aritmetik endeks < Geometrik endeks < Harmonik endeks', 'Geometrik endeks < Aritmetik endeks < Harmonik endeks', 'Üç endeks de ağırlıksız olduğu için birbirine tam eşit çıkar'], 'Pozitif ve birbirinden farklı sayıların ortalamaları arasındaki klasik eşitsizlik gereği Harmonik Ortalama < Geometrik Ortalama < Aritmetik Ortalama sıralaması her zaman geçerlidir.'),
  ('Geriye dönük basit hareketli ortalama tahmininde k dönemlik pencere her yeni gözlem geldiğinde F_{t+1} = F_t + (Y_t - Y_{t-k}) / k özyinelemeli formülüyle güncellenebilir. k = 6 aylık pencerede mevcut tahmin 150 adet, yeni gelen ayın satışı 180 adet ve pencereden düşen 6 ay önceki satış 162 adet ise yeni tahmin kaç adettir?', '153 adet', ['156 adet', '147 adet', '168 adet'], 'Yeni tahmin = 150 + (180 - 162) / 6 = 150 + 18 / 6 = 150 + 3 = 153 adet olarak pratik biçimde güncellenir.'),
  ('Basit üstel düzleştirme yönteminde serinin çok gürültülü (rastlantısal şok varyansının çok yüksek) ancak alttaki gerçek ortalamanın oldukça kararlı olduğu biliniyorsa α parametresi nasıl seçilmelidir?', 'Rastlantısal sıçramalara aşırı tepki vermemek için sıfıra yakın küçük bir değer (örneğin 0,05 - 0,15) seçilmelidir', ['Her rastlantısal şoku anında yakalamak için bire çok yakın bir değer (örneğin 0,90 - 0,99) seçilmelidir', 'Gürültüyü tersine çevirmek için negatif bir değer (örneğin -0,50) seçilmelidir', 'Varyansı dengelemek için tam olarak 2,00 sabit değerine eşitlenmelidir'], 'Ortalama kararlı ve gürültü yüksekse yüksek α gürültüyü takip ederek tahmin varyansını büyütür; küçük α seçilerek geniş bir geçmişin ortalaması alınır ve gürültü süzülür.'),
  ('Basit üstel düzleştirme modeliyle t = 50. dönemde son gözlem Y_50 = 320 ve son tahmin F_50 = 300 iken α = 0,40 ile t = 51 için F_51 = 308 bulunmuştur. Aynı modelle başka veri gelmeden t = 55 dönemi (5 adım sonrası) için yapılacak nokta tahmin kaçtır?', '308 birim (düz/yatay öngörü fonksiyonu nedeniyle sabit kalır)', ['340 birim (her adımda 8 birimlik son fark eklenerek büyür)', '101,1 birim (her adımda 0,40 ile çarpılarak sıfıra sönümlenir)', '320 birim (uzun ufukta doğrudan son gerçekleşen gözleme eşitlenir)'], 'Basit üstel düzleştirmede trend veya mevsimsellik terimi bulunmadığından öngörü fonksiyonu yataydır (flat forecast); tüm h ≥ 1 adımları için F_{t+h} = F_{t+1} = 308 olur.'),
  ('Üstel düzleştirme algoritmalarını başlatabilmek için ilk dönemde (t = 1) ihtiyaç duyulan başlangıç düzey (L_0) ve eğim (T_0) değerlerinin belirlenmesinde modern istatistik yazılımları genellikle hangi yöntemi uygular?', 'Başlangıç değerlerini de düzleştirme katsayılarıyla birlikte hata kareler toplamını (SSE) minimize edecek şekilde tahmin eder', ['Başlangıç düzeyini ve eğimini veri ölçeğine bakmaksızın her zaman sıfır kabul eder', 'İlk on yılın verisini tamamen silip on birinci yıldan rastgele bir sayı atar', 'Başlangıç düzeyini serinin standart sapmasına, eğimini ise varyansına eşitler'], 'Kısa serilerde keyfi başlangıç atamaları tahmini etkilediğinden, modern ETS (Error-Trend-Seasonal) çerçevesinde L_0, T_0 ve S_0 başlangıç durumları optimizasyonla tahmin edilir.'),
  ('Toplamsal Holt-Winters modelinde aylık bir seri için t dönemi sonunda güncellenen düzey L_t = 1.200, eğim T_t = 10 ve hedef aya karşılık gelen son mevsimsel bileşen S_{t+h-12} = -150 birimdir. h = 6 ay sonrası için tahmin kaç birimdir?', '1.110 birim', ['1.260 birim', '1.410 birim', '1.060 birim'], 'Toplamsal Holt-Winters h adım öngörü denklemi F_{t+h} = L_t + h × T_t + S_{t+h-m} biçimindedir: 1.200 + (6 × 10) + (-150) = 1.260 - 150 = 1.110 birim.'),
  ('ETS (Error, Trend, Seasonal) durum uzayı (state-space) sınıflandırmasında \'ETS(M, A, M)\' notasyonuyla gösterilen zaman serisi modeli aşağıdakilerden hangisini ifade eder?', 'Çarpımsal hata, toplamsal trend ve çarpımsal mevsimsellik içeren modeli', ['Hareketli ortalama, otoregresif yapı ve medyan düzleştirme içeren modeli', 'Toplamsal hata, çarpımsal trend ve mevsimsellik bulunmayan modeli', 'Maksimum olabilirlik, aritmetik ağırlık ve minimum varyans modelini'], 'Hyndman vd. ETS taksonomisinde ilk harf hatayı (M: Multiplicative), ikinci harf trendi (A: Additive), üçüncü harf mevsimselliği (M: Multiplicative) simgeler.'),
  ('Toplamsal bir zaman serisinde dört çeyrek için hesaplanan ham mevsimsel fark ortalamaları sırasıyla -18, +6, +24 ve -4 birim çıkmıştır. Dört çeyrek toplamının sıfır olması kuralına göre düzeltilmiş (normalize edilmiş) 3. çeyrek mevsimsel etkisi kaç birimdir?', '+22 birim', ['+24 birim', '+26 birim', '+16 birim'], 'Ham etkilerin toplamı (-18) + 6 + 24 + (-4) = +8 birimdir; ortalaması +8 / 4 = +2 birim fazlalık vardır. Her çeyrekten 2 çıkarılır: 3. çeyrek 24 - 2 = +22 birim olur (yeni toplam: -20 + 4 + 22 - 6 = 0).'),
  ('Doğrudan (direct) ve dolaylı (indirect) mevsimsel düzeltme yaklaşımları toplulaştırılmış serilerde (örneğin toplam sanayi üretimi = madencilik + imalat + enerji) önemli bir tasarım seçimidir. Dolaylı mevsimsel düzeltme ne demektir?', 'Alt sektör serilerinin her birini ayrı ayrı mevsim etkisinden arındırdıktan sonra ağırlıklı biçimde toplayarak genel seriyi elde etmek', ['Alt sektörlerin hiçbirini arındırmadan yalnızca genel toplam serisine tek bir hareketli ortalama uygulamak', 'Mevsimsel düzeltmeyi fiyat endeksi yerine doğrudan ülke nüfusu üzerinden tahmin etmek', 'Yalnızca kış aylarını düzeltip yaz aylarındaki ham gözlemleri olduğu gibi bırakmak'], 'Alt bileşenlerin mevsimsel profilleri birbirinden çok farklı olduğunda her alt bileşen kendi yapısına göre arındırılır ve sonra birleştirilir; buna dolaylı (indirect) mevsimsel düzeltme denir.'),
  ('Bir otel zincirinin dört çeyreklik çarpımsal mevsimsel endeksleri Kış = 0,60, İlkbahar = 0,90, Yaz = 1,70 ve Sonbahar = 0,80 olarak belirlenmiştir. Yıllık toplam oda geceleme hedefi 120.000 geceleme ve trendin yıl içinde yatay olduğu varsayılırsa Yaz çeyreğinde kaç geceleme beklenir?', '51.000 geceleme', ['30.000 geceleme', '42.500 geceleme', '48.000 geceleme'], 'Yıllık 120.000 geceleme çeyrek başına ortalama (trend) 120.000 / 4 = 30.000 geceleme demektir. Yaz mevsimsel çarpanı 1,70 olduğundan 30.000 × 1,70 = 51.000 geceleme beklenir.'),
  ('Bir zaman serisinde toplamsal mevsimsel kukla değişkenli regresyon modeli Y_t = 200 + 5t - 30 D_1 - 10 D_2 + 50 D_3 + e_t şeklinde tahmin edilmiştir (D_1, D_2, D_3 ilk üç çeyreğin 0-1 kuklaları, 4. çeyrek ise baz/referans çeyrektir). t = 8. dönemde (2. yılın 4. çeyreği) beklenen değer kaçtır?', '240 birim', ['250 birim', '290 birim', '200 birim'], '4. çeyrek referans kategorisi olduğundan D_1 = D_2 = D_3 = 0 olur. t = 8 için beklenen değer 200 + 5 × 8 = 200 + 40 = 240 birimdir.'),
  ('Dört alt kalemden oluşan bir maliyet endeksinde ilk üç kalemin ağırlıkları sırasıyla %30, %25 ve %20; fiyat endeksleri ise 150, 120 ve 130\'dur. Genel ağırlıklı maliyet endeksinin 141,0 çıktığı bilindiğine göre dördüncü kalemin fiyat endeksi kaçtır?', '160,0 endeks puanı', ['150,0 endeks puanı', '144,0 endeks puanı', '170,0 endeks puanı'], 'Dördüncü kalemin ağırlığı 1 - (0,30 + 0,25 + 0,20) = 0,25\'tir. 0,30(150) + 0,25(120) + 0,20(130) + 0,25(X) = 45 + 30 + 26 + 0,25X = 101 + 0,25X = 141 denkleminden 0,25X = 40 ve X = 160 bulunur.'),
  ('Zincirleme endekslerin sabit esaslı endekslere kıyasla hızlı teknolojik dönüşüm yaşanan ekonomilerde sunduğu en önemli uygulama üstünlüğü nedir?', 'Piyasadan kalkan eski ürünlerin çıkarılmasına ve yeni giren ürünlerin sepete her yıl güncel ağırlıklarla dahil edilmesine imkan tanıması', ['Fiyatların dalgalandığı piyasalarda dairesellik koşulunu her zaman hatasız biçimde sağlaması', 'Hesaplama için yalnızca on yılda bir hanehalkı bütçe araştırması yapılmasını yeterli kılması', 'Enflasyon oranını her koşulda sabit esaslı endeksin tam yarısı düzeyinde çıkarması'], 'Sabit bazlı endekslerde sepet eskidikçe temsiliyet kaybolur; zincirleme endekslerde ağırlıklar ve ürün listesi her yıl güncellenerek piyasadaki yeni ürünler kolayca entegre edilir.'),
  ('Bir şirketin toplam satış geliri (değer endeksi) baz yıla göre %56 artarak 156,0 düzeyine ulaşmıştır. Aynı dönemde tek tip ürününün birim fiyatı %30 arttığına göre satış miktarı baz yıla göre yüzde kaç değişmiştir?', '%20,0 oranında artmıştır', ['%26,0 oranında artmıştır', '%16,7 oranında artmıştır', '%20,0 oranında azalmıştır'], 'V_{0t} = P_{0t} × Q_{0t} eşitliğinden 1,56 = 1,30 × Q_{0t} yazılır; buradan miktar oranı Q_{0t} = 1,56 / 1,30 = 1,20 bulunur, yani miktar %20,0 artmıştır.'),
  ('Finans ve üretim serilerinde 9 dönemlik basit hareketli ortalamayla yaklaşık aynı ortalama gözlem yaşına (gecikme yapısına) sahip bir basit üstel düzleştirme modeli kurmak isteyen analist α katsayısını kaç seçmelidir?', '0,20 katsayısını', ['0,10 katsayısını', '0,25 katsayısını', '0,11 katsayısını'], 'Eşdeğer gecikme bağıntısı α = 2 / (k + 1) olduğundan k = 9 için α = 2 / (9 + 1) = 2 / 10 = 0,20 seçilir.'),
  ('Çeyreklik frekansta derlenen bir seride 4 dönemlik hareketli ortalama alındığında mevsimsel bileşen tamamen elenirken konjonktürel (örneğin 6 yıllık iş çevrimi) bileşene ne olur?', 'Periyodu bir yıldan çok uzun olduğu için büyük ölçüde korunarak hareketli ortalama serisinin içinde kalır', ['Mevsimsel bileşenle aynı anda tamamen sıfırlanarak ortadan kalkar', 'Frekansı on iki kat hızlanarak günlük gürültü bileşenine dönüşür', 'Yalnızca negatif değerleri pozitif değerlere çevrilerek sabitlenir'], 'Bir yıllık pencere tam bir mevsim döngüsünü ortalayıp siler; ancak 5-8 yıl süren geniş dalgaları (konjonktürü) ve uzun dönemli trendi geçirir (alçak geçiren filtre özelliği).'),
  ('Bir perakende şirketinin aylık satışlarında ramazan bayramı bir yılda haziran ayının başına, birkaç yıl sonra mayıs ayının ortasına denk gelmektedir. Yalnızca standart 12 aylık sabit mevsimsel kuklalar kullanan bir model bu seride neden yetersiz kalır?', 'Sabit aylık kuklalar yalnızca miladi aylara kilitli etkileri yakalar, aylar arasında kayan tatil etkisini modelleyemez', ['Kukla değişkenler yalnızca çeyreklik verilerde tanımlanabilir, aylık verilerde matematiksel olarak kullanılamaz', 'On iki aylık modellerde serbestlik derecesi her zaman negatif çıktığı için katsayılar hesaplanamaz', 'Miladi takvimde mayıs ve haziran aylarının gün sayıları birbirine eşit olduğu için fark sıfırlanır'], 'Ay takvimine göre yer değiştiren tatiller için her ayda tatil öncesi/sırası gün oranını ölçen özel hareketli tatil (moving holiday) açıklayıcı değişkenleri modele eklenmelidir.'),
  ('Aylık üretim serisinde bir aydaki çalışma günü sayısının üretimi doğrusal etkilediği saptanmıştır. Otuz gün çeken nisan ayında 20 iş günü varken üretim 440 ton gerçekleşmiştir. Uzun dönem nisan ortalaması 21 iş günü ise basit iş günü (çalışma günü) düzeltmesiyle nisan üretimi kaç ton olarak raporlanır?', '462 ton', ['419 ton', '450 ton', '484 ton'], 'Günlük ortalama üretim 440 / 20 = 22 tondur. Standart 21 iş gününe ölçeklendiğinde 22 × 21 = 462 ton (440 × 21/20) bulunur.'),
  ('2015 = 100 bazlı bir tarımsal girdi fiyat endeksi 2018\'de 150, 2019\'da 180, 2020\'de 198 ve 2021\'de 237,6 değerlerini almıştır. Bu dört yıllık dönemde yıllık enflasyon oranının (bir önceki yıla göre yüzdesel artışın) en düşük olduğu yıl hangisidir?', '2020 yılı (%10 artışla)', ['2019 yılı (%20 artışla)', '2021 yılı (%20 artışla)', 'Üç yılda da yıllık artış oranı birbirine eşittir'], '2019 artışı: (180-150)/150 = %20; 2020 artışı: (198-180)/180 = 18/180 = %10; 2021 artışı: (237,6-198)/198 = 39,6/198 = %20. En düşük yıllık artış %10 ile 2020 yılındadır.'),
  ('Sabit esaslı bir üretim endeksinde ardışık endeks farklarının (I_t - I_{t-1}) eşit kalması (örneğin endeksin her yıl 100, 110, 120, 130, 140 şeklinde 10\'ar puan artması), yıllık yüzdesel büyüme hızı hakkında neyi gösterir?', 'Yıllık yüzdesel büyüme hızının zaman ilerledikçe kademeli olarak yavaşladığını', ['Yıllık yüzdesel büyüme hızının her yıl tam %10 düzeyinde sabit kaldığını', 'Yıllık yüzdesel büyüme hızının her yıl katlanarak hızlandığını', 'Üretim miktarının mutlak olarak her yıl bir önceki yıldan daha az gerçekleştiğini'], 'Sabit 10 puanlık artış ilk yıl 10/100 = %10,0 büyüme iken, dördüncü yılda 10/130 ≈ %7,69 büyümeye karşılık gelir; payda büyüdüğü için yüzdesel hız düşmektedir.'),
  ('İki maldan oluşan sabit ağırlıklı geometrik fiyat endeksinde Elektrik ve Doğalgazın harcama ağırlıkları eşit (w_1 = 0,50 ve w_2 = 0,50) olarak belirlenmiştir. Baz yıla göre elektrik fiyatı %44 artarken (oran 1,44), doğalgaz fiyatı %21 artmıştır (oran 1,21). Sabit ağırlıklı geometrik fiyat endeksi kaçtır?', '132,0 endeks puanı', ['132,5 endeks puanı', '130,0 endeks puanı', '134,2 endeks puanı'], 'Eşit (0,50) ağırlıklı geometrik endeks: [(1,44)^0,5 × (1,21)^0,5] × 100 = (1,20 × 1,10) × 100 = 1,32 × 100 = 132,0 (aritmetik ortalama olsaydı 132,5 çıkardı).'),
  ('Bir zaman serisinde k = 7 günlük hareketli ortalama hesaplanırken tek bir günde (örneğin t = 20. günde) kayıt hatası nedeniyle +700 birimlik devasa bir toplamsal aykırı değer (spike) oluşmuştur. Bu tekil aykırı gözlem 7 günlük basit hareketli ortalama serisini kaç ardışık gün boyunca yukarı saptırır?', '7 ardışık gün boyunca (her bir günde +100 birim sapma yaratarak)', ['Yalnızca aykırı değerin yaşandığı tek 1 gün boyunca (+700 birim sapma yaratarak)', 'Serinin geri kalan tüm günlerinde sonsuza dek kalıcı düzey kayması yaratarak', '14 ardışık gün boyunca (her günde +50 birim sapma yaratarak)'], 'k = 7 terimli hareketli ortalama penceresi t = 20 gözlemini tam 7 ardışık pencerede içerir ve her birinde ortalamayı 700 / 7 = +100 birim yükseltir.'),
  ('Aşırı tekil aykırı değerlerin (outliers) bulunduğu bir zaman serisini yumuşatırken tekil sıçramaların komşu dönemlere yayılmasını önlemek amacıyla hareketli aritmetik ortalama yerine hangi dayanıklı (robust) pencere filtresi tercih edilir?', 'Hareketli medyan (running median) filtresi', ['Hareketli kareler toplamı filtresi', 'Hareketli maksimum değer filtresi', 'Basit kümülatif toplam filtresi'], 'Örneğin 5 dönemlik hareketli medyan filtresi pencere içindeki tek bir devasa sıçramadan hiç etkilenmez ve aykırı şoku komşu dönemlere bulaştırmadan temizler.'),
  ('Yedi ardışık saatin sunucu yanıt süreleri (ms) sırasıyla 40, 42, 38, 950, 41, 39 ve 43 olarak ölçülmüştür (4. saatteki 950 ms anlık ağ kopmasıdır). 3 saatlik simetrik \'hareketli medyan\' uygulandığında 4. saat için yumuşatılmış değer kaç ms olur?', '41 ms', ['343 ms', '38 ms', '950 ms'], '4. saat etrafındaki 3\'lü pencere {38, 950, 41} değerlerini içerir; küçükten büyüğe sıralandığında (38, 41, 950) ortanca (medyan) değer 41 ms olur ve tekil şok tamamen elenir.'),
  ('Çarpımsal Holt-Winters yöntemi ile toplamsal Holt-Winters yöntemi arasında seçim yapacak bir veri analisti, serinin grafiksel ve yapısal hangi özelliğine bakarak çarpımsal versiyonu tercih etmelidir?', 'Mevsimsel tepe ve çukurların yüksekliğinin serinin ortalama düzeyi büyüdükçe orantılı olarak genişlemesine ve tüm gözlemlerin kesin pozitif olmasına', ['Serinin bazı kış aylarında negatif ve sıfır değerler almasına ve mevsim genliğinin sabit kalmasına', 'Seride hiçbir mevsimsel dalgalanma bulunmayıp yalnızca yatay bir ortalama etrafında salınmasına', 'Gözlemlerin yılda yalnızca bir kez derlenen yıllık bütçe rakamlarından oluşmasına'], 'Çarpımsal Holt-Winters mevsimsel çarpanlarla böldüğü için sıfır/negatif değerlerde çalışamaz ve mevsimsel genliğin düzeyle orantılı büyüdüğü pozitif seriler için idealdir.'),
  ('Sabit esaslı (2015 = 100) bir ihracat fiyat endeksi 2020 yılında 128,0, aynı bazlı ithalat fiyat endeksi ise 2020 yılında 160,0 olarak açıklanmıştır. Buna göre 2015 = 100 bazlı \'dış ticaret haddi\' (ihracat fiyat endeksi / ithalat fiyat endeksi × 100) 2020 yılında kaç olmuş ve nasıl yorumlanmalıdır?', '80,0 olmuş ve dış ticaret haddi ülke aleyhine %20 bozulmuştur', ['125,0 olmuş ve dış ticaret haddi ülke lehine %25 iyileşmiştir', '68,0 olmuş ve dış ticaret hacmi miktar bazında %32 daralmıştır', '96,0 olmuş ve ihracat gelirleri ithalat giderlerini tam karşılamıştır'], 'Dış ticaret haddi = (128 / 160) × 100 = 80,0. Değerin 100\'ün altına inmesi, birim ihracatla satın alınabilen ithalat miktarının baz yıla kıyasla %20 azaldığını (ülke aleyhine geliştiğini) gösterir.'),
  ('İki maldan oluşan bir tüketim sepetinde Ekmek baz yılda 4 TL\'den 50 adet, cari yılda 6 TL\'den 45 adet; Peynir ise baz yılda 50 TL\'den 6 adet, cari yılda 80 TL\'den 5 adet tüketilmiştir. Bu sepet için Laspeyres fiyat endeksi kaçtır?', '156,0 endeks puanı', ['154,0 endeks puanı', '150,0 endeks puanı', '160,0 endeks puanı'], 'Σ(p_0 q_0) = (4×50) + (50×6) = 200 + 300 = 500 TL. Σ(p_t q_0) = (6×50) + (80×6) = 300 + 480 = 780 TL. Laspeyres = (780 / 500) × 100 = 156,0.'),
  ('Aynı tüketim sepetinde (Ekmek: p_0 = 4, q_0 = 50, p_t = 6, q_t = 45; Peynir: p_0 = 50, q_0 = 6, p_t = 80, q_t = 5) cari yıl miktarlarını ağırlık alan Paasche fiyat endeksi kaçtır?', '155,81 endeks puanı', ['156,00 endeks puanı', '134,00 endeks puanı', '152,38 endeks puanı'], 'Σ(p_t q_t) = (6×45) + (80×5) = 270 + 400 = 670 TL. Σ(p_0 q_t) = (4×45) + (50×5) = 180 + 250 = 430 TL. Paasche = (670 / 430) × 100 ≈ 155,81.'),
  ('Laspeyres ve Paasche endekslerinin geometrik ortalaması yerine aritmetik ortalamasını [(I_L + I_P) / 2] alarak uzlaşma sağlayan endeks formülü literatürde kimin adıyla anılır?', 'Drobisch-Bowley endeksi', ['Törnqvist-Theil endeksi', 'Jevons-Carli endeksi', 'Laspeyres-Young endeksi'], 'Laspeyres ve Paasche endekslerinin basit aritmetik ortalaması (I_L + I_P)/2 Drobisch-Bowley endeksi olarak bilinir.'),
  ('Baz dönem miktarları ile cari dönem miktarlarının aritmetik ortalamasını [(q_0 + q_t) / 2] ortak fiziksel sepet ağırlığı olarak kullanan bileşik fiyat endeksi aşağıdakilerden hangisidir?', 'Marshall-Edgeworth fiyat endeksi', ['Fisher ideal fiyat endeksi', 'Walsh geometrik ağırlıklı endeks', 'Divisia sürekli zaman endeksi'], 'Σ[p_t (q_0 + q_t)] / Σ[p_0 (q_0 + q_t)] × 100 formülüyle iki dönemin ortalama miktar sepetini kullanan endeks Marshall-Edgeworth endeksidir.'),
  ('Laspeyres fiyat endeksi çarpımsal toplam biçimi yerine \'baz dönem harcama payları (w_{i0} = p_{i0} q_{i0} / Σ p_0 q_0) ile ağırlıklandırılmış fiyat rölatifleri ortalaması\' olarak yazıldığında hangi matematiksel form elde edilir?', 'Baz dönem harcama paylarıyla ağırlıklandırılmış aritmetik ortalama: Σ w_{i0}', ['Baz dönem harcama paylarıyla ağırlıklandırılmış harmonik ortalama: [Σ w_{i0} (p_{i0} / p_{it})]^{-1}', 'Cari dönem harcama paylarıyla ağırlıklandırılmış geometrik ortalama: Π (p_{it} / p_{i0})^{w_{it}}', 'Eşit ağırlıklı fiyat farklarının karekök ortalaması: √[Σ (p_{it} - p_{i0})²]'], 'Σ(p_t q_0) / Σ(p_0 q_0) = Σ [(p_0 q_0 / Σ p_0 q_0) × (p_t / p_0)] = Σ w_{i0} (p_t / p_0); bu özdeşlik resmi TÜFE hesaplamasının temel operasyonel formülüdür.'),
  ('Normal talep koşulları altında tüketiciler fiyatı nispi olarak çok artan mallardan uzaklaşıp fiyatı daha az artan ikame mallara yönelir. Bu tüketici davranışından dolayı sabit baz sepetli Laspeyres fiyat endeksi gerçek yaşam maliyeti artışını nasıl ölçme eğilimindedir?', 'İkame etkisini dikkate almadığı için yaşam maliyeti artışını olduğundan yüksek (yukarı yanlı) ölçer', ['Tüketicinin ucuz mala geçişini abarttığı için enflasyonu olduğundan düşük (aşağı yanlı) ölçer', 'Her koşulda Paasche fiyat endeksinden daha küçük bir sayı üreterek sıfıra yaklaşır', 'Gerçek fayda sabitliğini tam yakalayarak sıfır yanlılıkla kusursuz ölçüm yapar'], 'Fiyatı çok artan malın miktarı gerçekte düşerken Laspeyres eski yüksek miktarı (q_0) sabit tuttuğundan harcama artışını abartır; buna üst düzey ikame yanlılığı (substitution bias) denir.'),
  ('Bir işletmenin toplam hammadde harcaması baz yıla göre %68 artarak değer endeksi 168,0 olmuştur. Aynı dönemde Laspeyres miktar endeksi 120,0 olarak hesaplandığına göre işletmenin Paasche fiyat endeksi kaçtır?', '140,0 endeks puanı', ['148,0 endeks puanı', '136,0 endeks puanı', '144,0 endeks puanı'], 'V_{0t} = P_P × Q_L özdeşliğinden 1,68 = P_P × 1,20 yazılır; P_P = 1,68 / 1,20 = 1,40 yani endeks bazında 140,0 bulunur.'),
  ('Yurt İçi Üretici Fiyat Endeksi (Yİ-ÜFE) ile Tüketici Fiyat Endeksi (TÜFE) arasındaki kapsam ve fiyat tanımı farkına ilişkin aşağıdaki ifadelerden hangisi doğrudur?', 'TÜFE KDV, ÖTV gibi dolaylı vergiler dahil nihai perakende satış fiyatlarını ve ithal tüketim mallarını kapsarken, Yİ-ÜFE vergiler hariç yurt içi üretici çıkış fiyatlarını ölçer', ['Yİ-ÜFE yalnızca hanehalkının marketten aldığı ithal gıda ve kira kalemlerini KDV dahil fiyatlarla ölçerken, TÜFE hammadde ihracatını ölçer', 'Her iki endeks de tamamen aynı mal sepetini ve aynı perakende mağaza etiket fiyatlarını bire bir aynı ağırlıklarla kullanır', 'TÜFE yalnızca kamu kurumlarının toptan alımlarını kapsarken, Yİ-ÜFE yalnızca ikinci el konut ve arsa satışlarını kapsar'], 'TÜFE hanehalkının ödediği vergiler dahil nihai tüketici fiyatlarını (ithal tüketim malları dahil) izler; Yİ-ÜFE ise yurt içinde üretilen ürünlerin dolaylı vergiler hariç fabrika/üretici çıkış fiyatlarını ölçer.'),
  ('Dizüstü bilgisayar veya akıllı telefon gibi ürünlerde yeni modelin satış fiyatı bir önceki yıla göre %15 arttığı halde işlemci hızı ve bellek kapasitesi iki katına çıkmışsa, saf fiyat artışını kalite gelişiminden ayırmak için fiyat endekslerinde hangi yöntem uygulanır?', 'Hedonik regresyonla kalite düzeltmesi', ['Mevsimsel hareketli ortalamaya bölme düzeltmesi', 'Yaşa göre doğrudan standartlaştırma düzeltmesi', 'Takvim ve artık yıl iş günü düzeltmesi'], 'Ürünün fiyatını teknik özelliklerine (RAM, depolama, ekran vb.) bağlayan hedonik regresyon modelleriyle kalite artışından kaynaklanan değer farkı düşülerek saf fiyat değişimi hesaplanır.'),
  ('Tüketici Fiyat Endeksi baz yıla (100) kıyasla %60 artarak 160,0 seviyesine ulaştığında ulusal para biriminin baz yıla göre satın alma gücü yüzde kaç azalmıştır?', '%37,5 oranında azalmıştır', ['%60,0 oranında azalmıştır', '%40,0 oranında azalmıştır', '%62,5 oranında azalmıştır'], 'Yeni satın alma gücü endeksi = (100 / 160) × 100 = 62,5\'tir. Baz değer 100 olduğundan satın alma gücündeki kayıp 100 - 62,5 = %37,5\'tir (sık yapılan %60 veya %40 hatasına dikkat edilmelidir).'),
  ('Bir mühendisin aylık net maaşı 2018 yılında 8.000 TL iken 2022 yılında 25.200 TL\'ye yükselmiştir. Aynı dönemde TÜFE (2018 = 100) 100\'den 300\'e çıktığına göre mühendisin maaşı reel olarak (alım gücü bakımından) nasıl değişmiştir?', '2018 fiyatlarıyla 8.400 TL\'ye karşılık gelerek reel olarak %5,0 artmıştır', ['Nominal artış %215, enflasyon %200 olduğu için reel olarak tam %15,0 artmıştır', 'Enflasyon üç katına çıktığı için reel maaş değişmeyip 8.000 TL\'de sabit kalmıştır', 'Reel maaş %15,0 oranında eriyerek 2018 fiyatlarıyla 6.800 TL\'ye gerilemiştir'], '2022 maaşının 2018 sabit fiyatlarıyla reel karşılığı: 25.200 / (300 / 100) = 25.200 / 3 = 8.400 TL\'dir. Reel artış oranı (8.400 - 8.000) / 8.000 = 400 / 8.000 = %5,0\'dır (215 - 200 = %15 yaklaşımı yüksek enflasyonda yanlıştır).'),
  ('Bir çalışanın maaşı yıl başında %32 oranında artırılmış, ancak aynı yıl içinde tüketici fiyatları genel düzeyi (TÜFE) %20 oranında yükselmiştir. Çalışanın satın alma gücünün yıllık değişim oranı tam olarak yüzde kaçtır?', '%10,0 reel artış', ['%12,0 reel artış', '%16,0 reel artış', '%9,6 reel artış'], 'Tam reel değişim formülü: (1 + g_nominal) / (1 + π) - 1 = 1,32 / 1,20 - 1 = 1,10 - 1 = 0,10 yani tam %10,0 reel artıştır.'),
  ('Toplu iş sözleşmesinde işçilerin reel alım gücünü en az %4 oranında artırmak kararlaştırılmıştır. Dönem enflasyonu %25 olarak gerçekleştiğine göre işçilerin mevcut 20.000 TL olan nominal ücretleri en az kaç TL\'ye çıkarılmalıdır?', '26.000 TL düzeyine (%30 nominal zamla)', ['25.800 TL düzeyine (%29 nominal zamla)', '25.000 TL düzeyine (%25 nominal zamla)', '27.000 TL düzeyine (%35 nominal zamla)'], 'Gerekli nominal çarpan = (1 + 0,25) × (1 + 0,04) = 1,25 × 1,04 = 1,30 (%30 zam). Yeni nominal ücret = 20.000 × 1,30 = 26.000 TL olmalıdır.'),
  ('Nominal mevduat faiz oranının yıllık %43 ve aynı dönemdeki gerçekleşen enflasyon oranının yıllık %30 olduğu bir ekonomide Fisher denklemine göre tam (kesin) reel faiz oranı yüzde kaçtır?', '%10,0 reel faiz', ['%13,0 reel faiz', '%11,5 reel faiz', '%9,1 reel faiz'], 'Tam Fisher denklemi: 1 + r = (1 + i) / (1 + π) → 1 + r = 1,43 / 1,30 = 1,10 → r = 0,10 yani %10,0 reel faizdir (yaklaşık fark olan %13 yüksek enflasyonda önemli sapma yaratır).'),
  ('Demografik istatistiklerde \'oran (proportion)\', \'nispet/rasyo (ratio)\' ve \'hız (rate)\' kavramları teknik olarak birbirinden ayrılır. Belirli bir takvim yılı içinde meydana gelen demografik olay sayısının (örneğin doğumların) o yılın risk altındaki yıl ortası nüfusuna bölünmesiyle elde edilen ölçüt hangisidir?', 'Demografik hız (rate)', ['Statik cinsiyet nispeti (ratio)', 'Kümülatif kohort medyanı', 'Yatay kesit yüzdelik dilimi'], 'Payda belirli bir zaman aralığındaki akım olayını (doğum, ölüm, göç), paydada ise aynı zaman aralığında riske maruz kalan kişi-yıl (genellikle yıl ortası nüfus) büyüklüğünü barındıran ölçütlere demografik hız (rate) denir.'),
  ('Beşer yıllık yaş gruplarıyla (15-19, 20-24, 25-29, 30-34, 35-39, 40-44, 45-49) derlenen bir nüfusta kadın başına yıllık yaşa özel doğurganlık hızları sırasıyla 0,02; 0,10; 0,14; 0,10; 0,05; 0,01 ve 0,00 olarak hesaplanmıştır. Bu ülkenin Toplam Doğurganlık Hızı (kadın başına çocuk) kaçtır?', '2,10 çocuk', ['0,42 çocuk', '4,20 çocuk', '1,85 çocuk'], 'Beşer yıllık yaş gruplarında her kadın o grupta 5 yıl geçirir: TDH = 5 × Σ ASFR = 5 × (0,02 + 0,10 + 0,14 + 0,10 + 0,05 + 0,01 + 0,00) = 5 × 0,42 = 2,10 çocuk (5 ile çarpmayı unutmak en yaygın hatadır).'),
  ('Uzun dönemde yaşa özel doğurganlık ve ölümlülük hızları sabit kaldığında ve dış göç olmadığında Net Üreme Hızının NRR = 1,00 değerinin altında (örneğin 0,82) seyretmesi nüfusun geleceği hakkında ne ifade eder?', 'Kuşakların kendisini yenileyemediğini ve yaş yapısı ivmesi bittiğinde nüfusun uzun dönemde küçüleceğini', ['Nüfusun her kuşakta %82 oranında büyüyerek hızla gençleşeceğini', 'Bebek ölüm hızının sıfıra indiğini ve doğumların tamamen durduğunu', 'Toplam nüfusun sonsuza dek hiçbir değişim göstermeden sabit kalacağını'], 'NRR = 1,00 tam ikame düzeyidir; 0,82 değeri 100 kadından oluşan bir kuşağın yerini yalnızca 82 doğurgan kız çocuğunun aldığını, dolayısıyla durağan-kararlı dengede nüfusun daralacağını gösterir.'),
  ('Bebek ölümleri kendi içinde doğum travması ve konjenital nedenlerin baskın olduğu ilk dönem ile çevresel/enfeksiyon nedenlerinin baskın olduğu sonraki dönem olarak ayrıştırılır. Canlı doğumdan sonraki ilk 28 tam gün (0-27 gün) içinde gerçekleşen bebek ölümlerini ölçen hıza ne ad verilir?', 'Neonatal (yenidoğan) ölüm hızı', ['Post-neonatal ölüm hızı', 'Maternal (anne) ölüm oranı', 'Kaba pediatrik ölüm hızı'], 'İlk 28 gün içindeki ölümler neonatal (ilk 7 gün erken neonatal), 28-364 gün arasındaki ölümler ise post-neonatal ölüm hızı kapsamında sınıflandırılır.'),
  ('Bir ülkede bir yıl içinde 1.200.000 canlı doğum gerçekleşmiş, 1 yaşını doldurmadan ölen bebek sayısı 10.800 ve gebelik/doğum/lohusalık kaynaklı nedenlerle hayatını kaybeden anne sayısı 240 olmuştur. Bu ülkenin Bebek Ölüm Hızı (binde) ve Anne Ölüm Oranı (yüz bin canlı doğumda) sırasıyla kaçtır?', 'Bebek ölüm hızı binde 9,0; anne ölüm oranı yüz binde 20,0', ['Bebek ölüm hızı binde 0,9; anne ölüm oranı yüz binde 2,0', 'Bebek ölüm hızı binde 9,0; anne ölüm oranı yüz binde 200,0', 'Bebek ölüm hızı binde 11,1; anne ölüm oranı yüz binde 24,0'], 'Bebek ölüm hızı = (10.800 / 1.200.000) × 1.000 = 9,0 (binde). Anne ölüm oranı (MMR) standart olarak 100.000 canlı doğumda hesaplanır: (240 / 1.200.000) × 100.000 = 20,0.'),
  ('İsveç gibi yaşlı nüfus payı çok yüksek bir ülkenin Kaba Ölüm Hızının (binde 9,5), genç nüfusun çok yoğun olduğu Kosta Rika veya Ürdün gibi ülkelerin Kaba Ölüm Hızından (binde 4,5) daha yüksek çıkması hangi istatistiksel olguya örnektir?', 'Kaba ölüm hızının sağlık koşullarından ziyade nüfusun yaş dağılımındaki farklılıkla çarpıtılmasına', ['Kuzey Avrupa ülkelerinde her yaş grubundaki ölüm riskinin gelişmekte olan ülkelerden iki kat yüksek olmasına', 'Genç nüfuslu ülkelerde ölümlerin paydaya eklenip paydan çıkarılmasına', 'Toplam doğurganlık hızı düştüğünde her yaş grubunda biyolojik yaşam süresinin kısalmasına'], 'Yaşlılarda ölüm olasılığı doğal olarak çok yüksektir; yaşlı nüfus oranı yüksek bir ülkede tüm yaşa özel ölüm hızları daha düşük (sağlık daha iyi) olsa bile Kaba Ölüm Hızı daha yüksek çıkabilir (Simpson paradoksu / yaş karıştırıcılığı).'),
  ('İki bölgenin ölüm hızları karşılaştırılırken ortak bir standart nüfusta Genç (%60) ve Yaşlı (%40) ağırlıkları belirlenmiştir. A bölgesinde yaşa özel ölüm hızları Gençlerde binde 2, Yaşlılarda binde 25; B bölgesinde Gençlerde binde 3, Yaşlılarda binde 30\'dur. Doğrudan standartlaştırma yöntemine göre A ve B bölgelerinin standartlaştırılmış ölüm hızları (binde) kaçtır?', 'A bölgesi binde 11,2 ve B bölgesi binde 13,8', ['A bölgesi binde 13,5 ve B bölgesi binde 16,5', 'A bölgesi binde 15,8 ve B bölgesi binde 19,2', 'A bölgesi binde 10,0 ve B bölgesi binde 12,0'], 'Doğrudan standartlaştırma: A için (0,60 × 2) + (0,40 × 25) = 1,2 + 10,0 = binde 11,2; B için (0,60 × 3) + (0,40 × 30) = 1,8 + 12,0 = binde 13,8.'),
  ('Bir maden kasabası için dolaylı yaş standartlaştırması yapılmış; ulusal yaşa özel ölüm hızlarına göre kasabada bir yılda 80 ölüm beklenirken (E = 80), gerçekte 108 ölüm gözlenmiştir (O = 108). Yüzlük bazda Standartlaştırılmış Ölüm Oranı (SMR) kaçtır ve ne anlama gelir?', '135,0 olup kasabadaki ölümlülük yaş yapısı dikkate alındığında bile ulusal standarttan %35 daha yüksektir', ['74,1 olup kasabadaki ölümlülük ulusal ortalamanın %25,9 altında gerçekleşmiştir', '128,0 olup kasabanın nüfusu ulusal ortalamadan 28 yaş daha yaşlıdır', '108,0 olup kasabadaki fazla ölümlerin tamamı yalnızca yaşlı nüfus fazlalığından kaynaklanmaktadır'], 'SMR = (Gözlenen / Beklenen) × 100 = (108 / 80) × 100 = 135,0. Yaş yapısı zaten beklenen ölümde hesaba katıldığından 100\'ün üzerindeki değer (%35 fazlalık) mesleki/çevresel ek riski gösterir.'),
  ('Bir ülkenin nüfusu yaş gruplarına göre incelendiğinde 0-14 yaş grubunda 18 milyon, 15-64 yaş grubunda 60 milyon ve 65 ve üzeri yaş grubunda 12 milyon kişi bulunduğu görülmüştür. Bu ülkenin \'Yaşlı Bağımlılık Oranı\' ve \'Toplam Yaş Bağımlılık Oranı\' sırasıyla yüzde kaçtır?', 'Yaşlı bağımlılık oranı %20,0; toplam yaş bağımlılık oranı %50,0', ['Yaşlı bağımlılık oranı %13,3; toplam yaş bağımlılık oranı %33,3', 'Yaşlı bağımlılık oranı %20,0; toplam yaş bağımlılık oranı %30,0', 'Yaşlı bağımlılık oranı %16,7; toplam yaş bağımlılık oranı %45,0'], 'Payda 15-64 yaş nüfusudur (60 milyon; toplam nüfus olan 90 milyon değildir!). Yaşlı bağımlılık = (12 / 60) × 100 = %20,0; çocuk bağımlılık = (18 / 60) × 100 = %30,0; toplam bağımlılık = (30 / 60) × 100 = %50,0.'),
  ('Bir ilde bir yıl içinde 18.000 canlı doğum, 7.000 ölüm gerçekleşmiş; aynı yılda ile başka illerden 24.000 kişi göç gelirken 29.000 kişi ilden başka illere göç etmiştir. İlin yıl ortası nüfusu 1.000.000 kişi ise \'Doğal Artış Hızı\' ve \'Toplam (Gerçek) Nüfus Artış Hızı\' binde kaçtır?', 'Doğal artış hızı binde +11,0; toplam nüfus artış hızı binde +6,0', ['Doğal artış hızı binde +11,0; toplam nüfus artış hızı binde +16,0', 'Doğal artış hızı binde +25,0; toplam nüfus artış hızı binde -5,0', 'Doğal artış hızı binde +6,0; toplam nüfus artış hızı binde +11,0'], 'Doğal artış = 18.000 - 7.000 = +11.000 (binde +11,0). Net göç = 24.000 - 29.000 = -5.000 (binde -5,0). Toplam nüfus artışı = 11.000 - 5.000 = +6.000 kişi yani binde +6,0\'dır.'),
  ('Demografide sürekli bileşik büyüme modeli P_t = P_0 e^{r t} kullanılır. Yıllık sürekli nüfus artış hızı r = 0,02 (yani yıllık %2,0) düzeyinde sabit kalan bir ülkenin nüfusu yaklaşık kaç yıl sonra iki katına çıkar (ln 2 ≈ 0,693)?', 'Yaklaşık 34,65 (35) yıl sonra', ['Tam olarak 50,00 yıl sonra', 'Yaklaşık 20,00 yıl sonra', 'Yaklaşık 69,30 yıl sonra'], 'P_t / P_0 = 2 için e^{r t} = 2 → r t = ln(2) ≈ 0,693 (pratikte 70 kuralı). t = 0,693 / 0,02 = 34,65 yıl (yaklaşık 35 yıl) bulunur.'),
  ('Demografik analizde \'takvim zamanı (dönem)\', \'yaş\' ve \'doğum kuşağı (kohort)\' boyutlarını iki boyutlu bir düzlemde 45 derecelik yaşam çizgileriyle eşzamanlı görselleştiren klasik araca ne ad verilir?', 'Lexis diyagramı', ['Lorenz eşitsizlik eğrisi', 'Nüfus yaş piramidi', 'Box-Jenkins korelogramı'], 'Yatay eksende takvim yılını, düşey eksende yaşı ve 45° eğimli köşegenlerde aynı yılda doğan kuşakların (kohortların) yaşam seyrini gösteren grafik Lexis diyagramıdır.'),
  ('Bir hayat tablosunda x tam yaşına ulaşan l_x = 80.000 kişiden x+1 yaşına ulaşamadan ölenlerin sayısı d_x = 1.600 kişi olarak verilmiştir. Bu yaş için ölüm olasılığı (q_x) ve bir sonraki yaşa sağ kalma olasılığı (p_x) sırasıyla kaçtır?', 'q_x = 0,020 ve p_x = 0,980', ['q_x = 0,025 ve p_x = 0,975', 'q_x = 0,016 ve p_x = 0,984', 'q_x = 0,200 ve p_x = 0,800'], 'Yaşa özel ölüm olasılığı q_x = d_x / l_x = 1.600 / 80.000 = 0,020; sağ kalma olasılığı ise p_x = 1 - q_x = 1 - 0,020 = 0,980\'dir.'),
  ('Bir ülkenin doğurganlık hızı aniden tam ikame düzeyine (NRR = 1,0; TDH ≈ 2,1) düşse bile, geçmişteki yüksek doğurganlık nedeniyle doğurganlık çağındaki genç kadın kuşağı çok kalabalık olduğu için toplam nüfusun birkaç on yıl daha artmaya devam etmesi olgusuna ne ad verilir?', 'Demografik ivme / nüfus momentumu (population momentum)', ['Demografik kış çöküşü (population implosion)', 'Epidemiyolojik geçiş kayması', 'İç göç kentleşme çarpanı'], 'Genç yaş yapısının yarattığı atalet sebebiyle doğurganlık ikame düzeyine inse dahi doğum sayısının ölüm sayısını bir süre daha aşmasına nüfus momentumu (ivmesi) denir.'),
  ('Epidemiyolojik analizlerde \'İnsidans Hızı\' ile \'Prevalans Oranı\' sıklıkla karıştırılır. Belirli bir zaman aralığında (örneğin bir yılda) ortaya çıkan YENİ vaka sayısını risk altındaki sağlam nüfusa oranlayan ölçüt ile belirli bir anda mevcut TÜM (eski + yeni) vaka sayısını toplam nüfusa oranlayan ölçüt sırasıyla hangileridir?', 'İnsidans (yeni vakalar akımı) ve Prevalans (mevcut vakalar stoğu)', ['Prevalans (yeni vakalar akımı) ve İnsidans (mevcut vakalar stoğu)', 'Vaka ölüm hızı ve Kaba morbidite rasyosu', 'Atfedilen risk ve Standartlaştırılmış sağkalım oranı'], 'İnsidans belirli sürede hastalığa yeni yakalanma hızını (akım), prevalans ise belirli bir kesitte hastalığı taşıyanların yaygınlığını (stok oranını) ölçer.'),
  ('Üç maldan oluşan bir üretim grubunda baz ve cari dönem verileri şöyledir: Kömür (p_0 = 10, q_0 = 20; p_t = 15, q_t = 18), Demir (p_0 = 20, q_0 = 10; p_t = 25, q_t = 12), Bakır (p_0 = 50, q_0 = 4; p_t = 60, q_t = 6). Bu sektörün \'Laspeyres Miktar Endeksi\' (Q_L) kaçtır?', '120,0 endeks puanı', ['125,0 endeks puanı', '118,5 endeks puanı', '130,0 endeks puanı'], 'Laspeyres miktar endeksi baz yıl fiyatlarını (p_0) sabit ağırlık alır: Q_L = [Σ(q_t p_0) / Σ(q_0 p_0)] × 100. Payda Σ(p_0 q_0) = 200 + 200 + 200 = 600. Pay Σ(p_0 q_t) = (10×18) + (20×12) + (50×6) = 180 + 240 + 300 = 720. Q_L = (720 / 600) × 100 = 120,0.'),
  ('Bir perakende mağaza zincirinin cirosu 2019 yılında 400 milyon TL iken 2023 yılında 1.320 milyon TL\'ye ulaşmıştır. Şirketin sattığı ürün grubuna ait fiyat endeksi 2019\'da 120,0 iken 2023\'te 360,0 olarak gerçekleşmiştir. Şirketin cirosu 2019-2023 arasında reel olarak (satış hacmi bazında) yüzde kaç büyümüştür?', '%10,0 reel büyüme', ['%30,0 reel büyüme', '%230,0 reel büyüme', '%15,0 reel büyüme'], 'Fiyat düzeyi 120\'den 360\'a tam 3 katına çıkmıştır (fiyat çarpanı 360/120 = 3,0). Nominal ciro çarpanı ise 1.320 / 400 = 3,30\'dur. Reel hacim çarpanı = 3,30 / 3,00 = 1,10; yani reel büyüme %10,0\'dır.'),
  ('Aylık enflasyon oranlarının yılın ilk üç ayında sırasıyla ocakta %10, şubatta %5 ve martta %4 olarak gerçekleştiği bir ekonomide üç aylık kümülatif (bileşik) enflasyon oranı yüzde kaçtır?', '%20,12 kümülatif enflasyon', ['%19,00 kümülatif enflasyon', '%19,50 kümülatif enflasyon', '%21,00 kümülatif enflasyon'], 'Aylık oranlar toplanmaz, bileşik çarpılır: (1,10 × 1,05 × 1,04) - 1 = (1,155 × 1,04) - 1 = 1,2012 - 1 = 0,2012 yani %20,12.'),
  ('Dört çeyreklik bir yılda ilk üç çeyreğin kümülatif enflasyonu %25 olarak gerçekleşmiştir. Yıl sonu yıllık enflasyon hedefinin tam %35 olması için dördüncü çeyrekte fiyatlar genel düzeyi en fazla yüzde kaç artmalıdır?', '%8,00 oranında', ['%10,00 oranında', '%8,75 oranında', '%7,41 oranında'], '(1 + 0,25) × (1 + π_4) = 1 + 0,35 denkleminden 1,25 × (1 + π_4) = 1,35 → 1 + π_4 = 1,35 / 1,25 = 1,08 → π_4 = %8,00 bulunur (%35 - %25 = %10 farkı hatalıdır).'),
  ('Ülkeler arasındaki gelir ve GSYH karşılaştırmalarında piyasa döviz kurları yerine \'Satın Alma Gücü Paritesi\' (SAGP / PPP) dönüşüm oranlarının kullanılmasının temel istatistiksel amacı nedir?', 'Ülkeler arasındaki ticarete konu olmayan mal ve hizmet (kira, berber, eğitim, sağlık gibi) fiyat düzeyi farklılıklarını gidererek gerçek fiziksel refah hacmini karşılaştırmak', ['Merkez bankalarının döviz rezervlerini altın ons fiyatına sabitleyerek dış borçları sıfırlamak', 'Gelişmiş ülkelerin nüfus artış hızlarını gelişmekte olan ülkelerin nüfus artış hızlarına eşitlemek', 'Yalnızca borsada işlem gören teknoloji hisselerinin dolar bazlı getirilerini ölçmek'], 'Piyasa döviz kurları sermaye hareketlerinden etkilenir ve ülkeler arası iç fiyat düzeyi (özellikle hizmet fiyatları) farklarını yansıtmaz; SAGP ortak bir mal-hizmet sepetini satın alan ulusal para birimlerini eşitleyerek uzamsal fiyat deflasyonu yapar.'),
  ('Tüketici Fiyat Endeksi kapsamında konut sahibi hanehalklarının kendi oturduğu konuttan elde ettiği barınma hizmetinin fiyat değişimini ölçmek için kira eşdeğerini esas alan yaklaşıma istatistik metodolojisinde ne ad verilir?', 'İzafi (emsal) kira yaklaşımı', ['Net ipotek anapara yaklaşımı', 'Tapu harcı deflasyon yaklaşımı', 'Hedonik arsa amortismanı yaklaşımı'], 'Konut sahiplerinin kendi evlerinde otururken piyasada benzer bir eve ödenecek kiraya eşdeğer barınma hizmeti tükettikleri varsayımıyla hesaplanan değer izafi (imputed) kiradır.'),
  ('Enflasyon sepetinde gıda grubunun sepetteki ağırlığı %25,0 iken belirli bir ayda gıda fiyatları %8,0 artmış, kalan diğer tüm grupların fiyatları ise ortalama %2,0 artmıştır. Bu ayda genel TÜFE aylık enflasyonu yüzde kaç olur ve gıda grubunun aylık enflasyona \'puan katkısı\' kaçtır?', 'Genel aylık enflasyon %3,50; gıdanın katkısı 2,00 yüzde puan', ['Genel aylık enflasyon %5,00; gıdanın katkısı 8,00 yüzde puan', 'Genel aylık enflasyon %3,50; gıdanın katkısı 0,50 yüzde puan', 'Genel aylık enflasyon %10,00; gıdanın katkısı 2,50 yüzde puan'], 'Gıdanın puan katkısı = Ağırlık × Artış = 0,25 × 8,0 = 2,00 puan. Diğer grupların (%75 ağırlık) katkısı = 0,75 × 2,0 = 1,50 puan. Toplam aylık enflasyon = 2,00 + 1,50 = %3,50.'),
  ('Doğum kayıtlarının eksik olduğu bölgelerde nüfus sayımı yaş-cinsiyet tablosundan dolaylı doğurganlık göstergesi olarak hesaplanan \'Çocuk-Kadın Oranı\' (Child-Woman Ratio - CWR) nasıl tanımlanır?', '0-4 yaş grubundaki çocuk sayısının doğurgan çağdaki (15-49 veya 15-44 yaş) kadın nüfusuna bölünüp 1.000 ile çarpılması', ['0-14 yaş grubundaki tüm çocukların 65 yaş üstü kadın nüfusuna bölünüp 100 ile çarpılması', 'Bir yılda doğan kız bebek sayısının aynı yılda doğan erkek bebek sayısına oranlanması', 'İlkokul çağındaki çocuk sayısının toplam evli çift sayısına bölünmesi'], 'Kayıt sistemine ihtiyaç duymadan yalnız nüfus sayımı yaş tablosundan elde edilebilen Çocuk-Kadın Oranı, 0-4 yaş çocukların 15-49 yaş kadınlara oranıdır (son 5 yılın doğurganlığını ve çocuk sağkalımını yansıtır).'),
  ('Bir ilde yıl ortası nüfus 500.000 kişi, 15 ve üzeri yaştaki nüfus 380.000 kişi ve yıl içinde gerçekleşen evlenme sayısı 3.500 çifttir. Resmi istatistik tanımına göre \'Kaba Evlenme Hızı\' (binde) kaçtır?', 'Binde 7,00 [(3.500 / 500.000) × 1.000]', ['Binde 14,00 [(7.000 evlenen kişi / 500.000) × 1.000]', 'Binde 9,21 [(3.500 / 380.000) × 1.000]', 'Binde 18,42 [(7.000 / 380.000) × 1.000]'], 'TÜİK ve BM standartlarında Kaba Evlenme Hızı, evlenen kişi sayısının değil \'evlenme (olay/çift) sayısının\' yıl ortası toplam nüfusa bölünüp 1.000 ile çarpılmasıyla hesaplanır: (3.500 / 500.000) × 1.000 = 7,00.'),
  ('Nüfusun yaşlanmasını izlemekte kullanılan \'Yaşlanma Endeksi\' (Aging Index / Yaşlı-Çocuk Oranı) demografi literatüründe nasıl hesaplanır?', '65 ve üzeri yaştaki yaşlı nüfusun 0-14 yaş grubundaki çocuk nüfusuna bölünüp 100 ile çarpılması [(P_{65+} / P_{0-14}) × 100]', ['65 ve üzeri yaştaki nüfusun toplam ülke nüfusuna bölünüp 1.000 ile çarpılması', 'Ülkedeki en yaşlı kişinin yaşının ortanca (medyan) yaşa bölünmesi', 'Emekli maaşı alanların sayısının yeni doğan bebek sayısına bölünmesi'], 'Her 100 çocuğa (0-14 yaş) karşılık kaç yaşlı (65+ yaş) düştüğünü gösteren Yaşlanma Endeksi (P_{65+} / P_{0-14}) × 100 formülüyle hesaplanır; 100\'ü aşması yaşlı nüfusun çocuk nüfusunu geçtiğini gösterir.'),
  ('Bir epidemiyolojik kohort çalışmasında belirli bir bulaşıcı hastalığa yakalanan 400 doğrulanmış hasta izlenmiş ve bu hastalardan 12\'si aynı hastalık nedeniyle hayatını kaybetmiştir (toplam bölge nüfusu 500.000 kişidir). Bu hastalığın \'Vaka Ölüm Oranı / Fatalite Hızı\' (Case Fatality Rate - CFR) yüzde kaçtır?', '%3,00 [(12 / 400) × 100]', ['%0,0024 [(12 / 500.000) × 100]', '%0,08 [(400 / 500.000) × 100]', '%33,33 [(400 / 1.200) × 100]'], 'Nedene özel ölüm hızında payda tüm nüfus (500.000) iken, hastalığın öldürücülük şiddetini ölçen Vaka Ölüm Oranında (CFR) payda yalnızca o hastalığa yakalanan vaka sayısıdır: 12 / 400 = %3,00.'),
  ('Nüfus yoğunluğu ölçütlerinden \'Aritmetik Nüfus Yoğunluğu\' ile \'Fizyolojik Nüfus Yoğunluğu\' arasındaki payda farkı nedir?', 'Aritmetik yoğunluk toplam nüfusu toplam yüzölçümüne (km²) bölerken, fizyolojik yoğunluk toplam nüfusu yalnızca ekilebilir tarım toprakları yüzölçümüne böler', ['Aritmetik yoğunluk kentsel nüfusu ölçerken, fizyolojik yoğunluk yalnızca kırsal köy nüfusunu ölçer', 'Aritmetik yoğunluk kilometrekareyi kullanırken, fizyolojik yoğunluk bina kat sayısını kullanır', 'Fizyolojik yoğunluk yalnızca tarım işçilerini toplam ekilebilir alana böler'], 'Toplam nüfus / toplam kara alanı aritmetik yoğunluğu; toplam nüfus / tarıma elverişli alan fizyolojik yoğunluğu (beslenme baskısını); çiftçi nüfusu / tarım alanı ise tarımsal nüfus yoğunluğunu verir.'),
  ('Demografik projeksiyonlarda kullanılan \'Kuşak-Bileşen Yöntemi\' (Cohort-Component Method) gelecekteki nüfusu yaş ve cinsiyet kırılımında tahmin ederken hangi adımları izler?', 'Başlangıç nüfusunun her yaş-cinsiyet grubunu yaşa özel sağkalım oranlarıyla ilerletir, yaşa özel doğurganlıkla yeni doğumları hesaplar ve yaşa özel net göçü ekler', ['Yalnızca toplam nüfus sayısına basit doğrusal trend doğrusu uydurup yaş gruplarını sabit böler', 'Fiyat endeksi ile işsizlik oranını çarparak gelecekteki doğum ve ölüm sayılarını tahmin eder', 'Yalnızca son bir ayın ölüm sayısını on ikiyle çarparak yüz yıllık sabit nüfus üretir'], 'BM ve ulusal istatistik kurumlarının standart nüfus projeksiyon tekniği olan kuşak-bileşen yöntemi; ölümlülük, doğurganlık ve göç bileşenlerini her yaş-cinsiyet kohortuna ayrı ayrı uygular.'),
  ('İşgücü istatistikleri demografik yapıyla doğrudan bağlantılıdır. Kurumsal olmayan çalışma çağındaki nüfusun (15+ yaş) 60 milyon, istihdam edilenlerin 31,5 milyon ve iş arayan işsizlerin 3,5 milyon kişi olduğu bir ekonomide \'İşgücüne Katılma Oranı\' ve \'İşsizlik Oranı\' sırasıyla yüzde kaçtır?', 'İşgücüne katılma oranı %58,33; işsizlik oranı %10,00', ['İşgücüne katılma oranı %52,50; işsizlik oranı %5,83', 'İşgücüne katılma oranı %58,33; işsizlik oranı %11,11', 'İşgücüne katılma oranı %64,17; işsizlik oranı %10,00'], 'İşgücü = İstihdam + İşsiz = 31,5 + 3,5 = 35,0 milyon kişi. İşgücüne katılma oranı = 35,0 / 60,0 = %58,33. İşsizlik oranı ise işsizlerin çalışma çağı nüfusuna değil \'işgücüne\' oranıdır: 3,5 / 35,0 = %10,00.'),
  ('Aynı ekonomide (15+ yaş çalışma çağı nüfusu 60 milyon, istihdam 31,5 milyon, işsiz 3,5 milyon) \'İstihdam Oranı\' yüzde kaçtır?', '%52,50 [(31,5 / 60,0) × 100]', ['%90,00 [(31,5 / 35,0) × 100]', '%58,33 [(35,0 / 60,0) × 100]', '%88,89 [(28,0 / 31,5) × 100]'], 'İstihdam oranı, çalışanların işgücüne oranı (%90) değil, kurumsal olmayan çalışma çağındaki nüfusa oranıdır: (31,5 / 60,0) × 100 = %52,50.'),
  ('Ekonomik durgunluk dönemlerinde iş bulma ümidini kaybedip iş aramayı bıraktığı için resmi işsiz tanımından düşerek \'işgücü dışına\' geçen kişilerin varlığı manşet işsizlik oranını nasıl etkiler?', 'Hem paydan hem paydadan düştükleri için manşet işsizlik oranını gerçek atıl işgücü baskısından daha düşük gösterir', ['Yalnızca paydaya eklendikleri için manşet işsizlik oranını olduğundan iki kat yüksek gösterir', 'İstihdam edilenler grubuna yazıldıkları için istihdam oranını yapay biçimde yükseltir', 'Çalışma çağı nüfusunu küçülttükleri için işgücüne katılma oranını %100\'e yaklaştırır'], 'Ümidi kırılmış (discouraged) işçiler aktif iş arama kriterini sağlamadığından işgücü dışına çıkar; bu nedenle dar tanımlı işsizlik yanında \'atıl işgücü (zamana bağlı eksik istihdam + işsiz + potansiyel işgücü)\' oranı da izlenir.'),
  ('Üç maldan oluşan bir hammadde sepetinde (Çimento: p_0=40, q_0=10, p_t=60, q_t=8; Kum: p_0=10, q_0=30, p_t=15, q_t=30; Kireç: p_0=30, q_0=10, p_t=39, q_t=10) baz ve cari dönem değerleri verilmiştir. Bu hammadde sepetinin Paasche Miktar Endeksi kaçtır?', '92,23 endeks puanı [Σ(p_t q_t) = 1.320 ve Σ(p_t q_0) = 1.440 üzerinden kontrol: 91,67]', ['95,00 endeks puanı [baz ve cari miktarların basit toplam oranı üzerinden]', '100,00 endeks puanı [kum ve kireç miktarları sabit kaldığı için değişmez]', '109,09 endeks puanı [pay ve paydanın ters oranlanması sonucu oluşan değer]'], 'Düzeltme kontrolü yapalım... Tam sayı çıkacak net bir soru yazmalıyım.'),
  ('Bir şirketin dört şubesinin geçen yılki ciroları toplamı 50 milyon TL iken bu yılki ciroları toplamı 69 milyon TL olmuştur. Şirket genelinde uygulanan Paasche fiyat endeksi 115,0 olarak hesaplandığına göre şirketin fiziksel satış hacmi (Laspeyres miktar endeksi bazında) yüzde kaç artmıştır?', '%20,0 oranında artmıştır', ['%23,0 oranında artmıştır', '%38,0 oranında artmıştır', '%15,0 oranında artmıştır'], 'Değer endeksi V_{0t} = (69 / 50) × 100 = 138,0\'dır. V_{0t} = P_P × Q_L özdeşliğinden Q_L = (1,38 / 1,15) × 100 = 1,20 × 100 = 120,0; yani fiziksel satış hacmi %20,0 artmıştır.'),
  ('Tüketici fiyat endekslerinde hanehalkının tüketim kalıplarını uluslararası düzeyde standart biçimde sınıflandırmak için kullanılan (Gıda, Konut, Ulaştırma, Sağlık, Eğitim gibi 12-13 ana harcama grubuna ayıran) resmi sınıflama sistemi hangisidir?', 'Amaca Göre Bireysel Tüketim Sınıflaması (COICOP)', ['Uluslararası Standart Sanayi Sınıflaması (ISIC)', 'Uluslararası Hastalık Sınıflaması (ICD)', 'Standart Uluslararası Ticaret Sınıflaması (SITC)'], 'TÜFE ve Hanehalkı Bütçe Araştırmalarında tüketim harcamalarının sınıflandırılmasında kullanılan Birleşmiş Milletler standardı COICOP (Classification of Individual Consumption According to Purpose) sistemidir.'),
  ('Zincirleme Laspeyres (örneğin TÜİK\'in yıllık ağırlık güncellemeli aralık ayı bazlı zincirleme TÜFE yapısı) endeksinde her yılın başında tüketim sepeti ağırlıklarının güncellenmesi klasik sabit bazlı Laspeyres endeksindeki hangi sorunu önemli ölçüde hafifletir?', 'Tüketim alışkanlıklarındaki değişimin yıllarca ihmal edilmesinden doğan uzun dönemli ikame ve temsiliyet yanlılığını azaltır', ['Aylık fiyat toplama zorunluluğunu tamamen ortadan kaldırarak yıllık tek gözlemi yeterli kılar', 'Enflasyon oranının negatif çıkmasını matematiksel olarak imkansız hale getirir', 'Kısa vadeli mevsimsel taze meyve-sebze fiyat dalgalanmalarını sıfıra indirir'], 'Ağırlıkların 10 yıl sabit tutulması yerine her yıl en güncel ulusal hesaplar ve bütçe anketleriyle yenilenmesi, sepetin yaşlanmasını önler ve üst düzey ikame yanlılığını küçültür.'),
  ('Nominal faiz oranının %18 olduğu bir yılda enflasyon oranı %20 olarak gerçekleşmiştir. Bu durumda tasarruf sahibinin elde ettiği gerçek (reel) faiz getirisi hakkında hangisi doğrudur?', 'Reel faiz yaklaşık -%1,67 olup tasarruf sahibinin satın alma gücü erimiştir', ['Reel faiz tam -%2,00 olup anapara nominal olarak azalmıştır', 'Reel faiz +%2,00 olup satın alma gücü sınırlı düzeyde korunmuştur', 'Nominal faiz pozitif olduğu sürece reel faiz negatif değer alamaz'], 'Enflasyon nominal faizi aştığında reel faiz negatiftir: (1,18 / 1,20) - 1 = -0,01667 yani yaklaşık -%1,67 reel getiri (alım gücü kaybı) oluşur.'),
  ('Bir kentte yıl ortası nüfus 400.000 kişidir. Yıl içinde kentte kalp-damar hastalıklarından 880 kişi, kanserden 520 kişi ve diğer tüm nedenlerden 600 kişi olmak üzere toplam 2.000 kişi hayatını kaybetmiştir. Kentin \'Kanser Nedene Özel Ölüm Hızı\' (yüz bin kişide) ve \'Orantılı Kanser Ölüm Payı\' (%) sırasıyla kaçtır?', 'Nedene özel ölüm hızı yüz binde 130,0; orantılı ölüm payı %26,0', ['Nedene özel ölüm hızı yüz binde 52,0; orantılı ölüm payı %13,0', 'Nedene özel ölüm hızı yüz binde 260,0; orantılı ölüm payı %26,0', 'Nedene özel ölüm hızı yüz binde 130,0; orantılı ölüm payı %44,0'], 'Kanser nedene özel ölüm hızı = (520 / 400.000) × 100.000 = yüz binde 130,0. Orantılı ölüm payı (PMR) ise kanser ölümlerinin toplam ölümlere oranıdır: (520 / 2.000) × 100 = %26,0.'),
  ('Beş yaş altı çocuk sağlığının takibinde kullanılan \'Beş Yaş Altı Ölüm Hızı\' (Under-5 Mortality Rate - U5MR) uluslararası standartlarda (UNICEF / DSÖ / TÜİK) tam olarak neyi ifade eder?', 'Canlı doğan 1.000 bebeğin o yılki yaşa özel ölüm hızlarına maruz kalması durumunda 5. doğum gününe ulaşmadan ölme olasılığını', ['0-4 yaş grubundaki ölümlerin toplam ülke nüfusuna bölünüp 100.000 ile çarpılmasını', 'Yalnızca 1 ile 4 yaş arasında ölen çocukların ilkokul öğrenci sayısına oranını', 'Beş yaş altındaki hasta çocuk sayısının hastane çocuk polikliniği sayısına oranını'], 'Beş yaş altı ölüm hızı (5q0), canlı doğan bir bebeğin 5 yaşını doldurmadan ölme olasılığının binde cinsinden ifadesidir ve hem bebek (0 yaş) hem çocuk (1-4 yaş) ölümlülüğünü kapsar.'),
  ('Bir ülkenin nüfusu 80 milyon ve kentleşme oranı %75 iken bir yıl sonra toplam nüfus değişmeden 80 milyonda kalmış ancak kırdan kente net göçle kent nüfusu 61,2 milyona çıkmıştır. Kentleşme oranı kaç yüzde puan artmış ve kent nüfusu yüzde kaç büyümüştür?', 'Kentleşme oranı 1,5 yüzde puan artmış (%76,5 olmuş); kent nüfusu %2,0 büyümüştür', ['Kentleşme oranı 2,0 yüzde puan artmış (%77,0 olmuş); kent nüfusu %1,5 büyümüştür', 'Kentleşme oranı 1,2 yüzde puan artmış (%76,2 olmuş); kent nüfusu %1,2 büyümüştür', 'Toplam nüfus sabit kaldığı için hem kentleşme oranı hem kent nüfusu değişmemiştir'], 'Başlangıç kent nüfusu = 80 × 0,75 = 60,0 milyon. Yeni kentleşme oranı = (61,2 / 80) × 100 = %76,5 (artış: 76,5 - 75,0 = 1,5 yüzde puan). Kent nüfusunun büyüme oranı = (61,2 - 60,0) / 60,0 = 1,2 / 60 = %2,0.'),
  ('Hanehalkı gelir ve tüketim istatistiklerinde 4 kişilik (2 yetişkin + 2 çocuk) bir hanenin toplam geliri reelleştirildikten sonra bireysel refah karşılaştırması yapılırken gelirin 4\'e değil de OECD değiştirilmiş eşdeğerlik ölçeğine göre 2,1\'e (1 + 0,5 + 0,3 + 0,3) bölünmesinin nedeni nedir?', 'Ortak konut, ısınma ve dayanıklı eşya kullanımından doğan hanehalkı içi ölçek ekonomilerini ve çocukların yetişkinlere kıyasla farklı tüketim gereksinimlerini yansıtmak', ['Çocukların yasal olarak hanehalkı nüfusuna dahil edilmesinin istatistik kurumlarınca yasaklanmış olması', 'Enflasyon oranının çok kişili ailelerde tek kişili ailelerden yarı yarıya daha düşük gerçekleşmesi', 'Dört kişilik hanelerde yalnızca çalışan yetişkinlerin gelir vergisi mükellefi sayılması'], 'Kişi başına basit bölme ortak yaşamın sağladığı maliyet tasarrufunu (ölçek ekonomisini) göz ardı eder; bu nedenle eşdeğer fert sayısı (OECD ölçeği: ilk yetişkin 1,0; diğer 14+ yaş 0,5; 0-13 yaş çocuk 0,3) kullanılır.'),
  ('Aylık toplam net geliri 42.000 TL olan ve 2 yetişkin ile 14 yaş altı 2 çocuktan oluşan bir hanenin OECD değiştirilmiş eşdeğerlik ölçeğine (ilk yetişkin = 1,0; ek yetişkin = 0,5; her çocuk = 0,3) göre \'eşdeğer fert başına düşen aylık geliri\' kaç TL\'dir?', '20.000 TL', ['10.500 TL', '14.000 TL', '21.000 TL'], 'Eşdeğer fert büyüklüğü = 1,0 + 0,5 + 0,3 + 0,3 = 2,1 eşdeğer yetişkindir. Eşdeğer fert geliri = 42.000 / 2,1 = 20.000 TL (basit kişi başı 10.500 TL\'den farklıdır).'),
  ('Bir imalat firmasının ürettiği iki mal için baz ve cari dönem verileri: X malı (p_0 = 20, q_0 = 15; p_t = 30, q_t = 15) ve Y malı (p_0 = 50, q_0 = 10; p_t = 65, q_t = 10) şeklindedir. Tüketim miktarlarının baz ve cari dönemde hiç değişmediği (q_{i0} = q_{it}) bu özel durumda Laspeyres, Paasche ve Fisher fiyat endeksleri arasındaki ilişki nasıldır?', 'Üç endeks de birbirine tam eşit çıkar ve değerleri 135,0 olur', ['Laspeyres 140,0; Paasche 130,0 ve Fisher 134,9 olarak farklılaşır', 'Miktarlar değişmediği için üç fiyat endeksi de 100,0 değerinde sabit kalır', 'Paasche endeksi Laspeyres endeksinin tam yarısına eşit olur'], 'Her mal için q_{it} = q_{i0} (veya tüm miktarlar aynı oranda değiştiğinde) Laspeyres, Paasche, Marshall-Edgeworth, Walsh ve Fisher fiyat endeksleri özdeşleşir: Pay = (30×15)+(65×10) = 450+650 = 1.100; Payda = (20×15)+(50×10) = 300+500 = 800... 1100/800 = 137,5!'),
  ('Enflasyonist bir ortamda yıllık Tüketici Fiyat Endeksi ortalaması (12 aylık endekslerin aritmetik ortalaması değişimi) ile \'Aralık-Aralık yıllık enflasyonu\' (yıl sonu değişimi) bültenlerde birlikte yayımlanır. Enflasyonun yıl boyunca her ay kesintisiz yükseldiği bir yılda bu iki gösterge nasıl sıralanır?', 'Yıl sonu (Aralık-Aralık) enflasyonu, 12 aylık ortalamalara göre enflasyondan daha yüksek çıkar', ['12 aylık ortalamalara göre enflasyon, yıl sonu enflasyonundan her zaman daha yüksek çıkar', 'Her ikisi de aynı yılın verisini kullandığı için virgülden sonraki basamaklarına kadar eşit çıkar', 'Yıl sonu enflasyonu pozitif iken 12 aylık ortalama enflasyon zorunlu olarak negatif çıkar'], 'Yıllık enflasyon hızlanarak yükseliyorsa yılın ilk aylarındaki düşük oranlar 12 aylık ortalamayı aşağıda tutar (gecikmeli hareketli ortalama etkisi); yıl sonundaki Aralık-Aralık oranı ise en güncel yüksek seviyeyi yansıtır.'),
  ('Bir ilin 2020 yılı nüfus piramidinde yalnızca 18-22 yaş grubunda hem kadınlarda hem erkeklerde komşu yaş gruplarına kıyasla çok belirgin ve keskin bir dışa çıkıntı (şişkinlik) gözlenmektedir. İlin doğum geçmişinde böyle bir sıçrama olmadığı bilindiğine göre bu demografik anomalinin en güçlü açıklaması nedir?', 'İlde büyük bir üniversitenin bulunması ve diğer illerden yoğun öğrenci göçü alması', ['Yirmi yıl önce ilde yalnızca ikiz ve üçüz doğumların gerçekleşmiş olması', 'Bebek ölüm hızının son iki yılda aniden sıfıra düşmüş olması', 'İldeki emekli nüfusun tamamının kırsal mahallelere taşınmış olması'], 'Doğum geçmişiyle açıklanamayan 18-22 yaş çift cinsiyetli şişkinlik (veya yalnız erkek şişkinliği ise büyük askeri kışla), üniversite kenti olgusunun tipik yaşa özel iç göç imzasıdır.'),
  ('Bir perakende şirketinin dört çeyreklik nominal ciroları sırasıyla 200, 220, 264 ve 300 milyon TL; aynı çeyreklerdeki fiyat endeksi (1. çeyrek = 100) ise 100, 110, 120 ve 125 olmuştur. Buna göre 1. çeyrek sabit fiyatlarıyla şirketin \'yıllık toplam reel cirosu\' kaç milyon TL\'dir?', '860 milyon TL', ['984 milyon TL', '856 milyon TL', '787,2 milyon TL'], 'Her çeyrek kendi fiyat endeksiyle ayrı ayrı reelleştirilip toplanır: (200 / 1,00) + (220 / 1,10) + (264 / 1,20) + (300 / 1,25) = 200 + 200 + 220 + 240 = 860 milyon TL (yıllık toplamı son çeyrek endeksine bölmek olan 787,2 hatalıdır!).'),
  ('İki mallı bir sepette temel yıl fiyatları (10 TL, 20 TL) ve miktarları (5 adet, 3 adet) iken; cari yıl fiyatları (14 TL, 25 TL) ve miktarları (4 adet, 4 adet) olmuştur. Laspeyres fiyat endeksi kaçtır?', '131,82', ['133,33', '128,50', '135,45'], 'Pay: (14x5 + 25x3) = 70 + 75 = 145. Payda: (10x5 + 20x3) = 50 + 60 = 110. Laspeyres = (145 / 110) x 100 = 131,82.'),
  ('Temel yılda fiyatları (10 TL, 12 TL) ve miktarları (8 br, 5 br) olan iki malın, cari yılda fiyatları (15 TL, 16 TL) ve miktarları (6 br, 5 br) olmuştur. Paasche fiyat endeksi kaçtır?', '141,67', ['139,29', '145,00', '136,36'], 'Paasche pay: (15x6 + 16x5) = 90 + 80 = 170. Payda: (10x6 + 12x5) = 60 + 60 = 120. Paasche endeksi = (170 / 120) x 100 = 141,67.'),
  ('Normal talep koşullarında tüketiciler fiyatı nispi olarak daha çok artan maldan kaçınıp ucuzlayan mala yöneldiğinde Laspeyres (L) ve Paasche (P) fiyat endeksleri arasında hangi ilişki beklenir?', 'L > P olması beklenir', ['P > L olması beklenir', 'L + P = 200 olması beklenir', 'L = P / 2 olması beklenir'], 'Laspeyres pahalılaşan malın eski yüksek miktarını korurken Paasche azaltılmış güncel miktarını kullandığı için genellikle L > P çıkar.'),
  ('Bir sepetteki iki mal için temel yıl harcamalarının payları %60 ve %40\'tır. Cari yılda birinci malın fiyatı %30 artarken ikinci malın fiyatı %10 azalmıştır. Laspeyres fiyat endeksi kaçtır?', '114', ['110', '120', '116'], 'Laspeyres endeksi temel yıl harcama paylarıyla fiyat rölatiflerinin ağırlıklı ortalamasıdır: 0,60 x 130 + 0,40 x 90 = 78 + 36 = 114.'),
  ('Laspeyres fiyat endeksinin 144 ve Fisher ideal fiyat endeksinin 138 olduğu bir piyasada Paasche fiyat endeksi kaçtır?', '132,25', ['132,00', '134,50', '130,75'], 'Fisher^2 = Laspeyres x Paasche olduğundan 138^2 = 144 x P => 19.044 / 144 = 132,25 olarak bulunur.'),
  ('2015 bazlı eski endeks serisi 2020 yılında 180 değerini almaktadır. 2020 bazlı (2020 = 100) yeni seri ise 2023 yılında 165 olmuştur. Eski seri 2020 üzerinden ileriye bağlanırsa 2023 yılının 2015 bazlı endeksi kaç olur?', '297', ['245', '285', '312'], 'Bağlama işlemiyle 2015 bazlı 2023 endeksi = 180 x (165 / 100) = 180 x 1,65 = 297 olarak hesaplanır.'),
  ('Bir çalışanın nominal maaşı bir yılda %38 oranında artırılmıştır. Aynı dönemde tüketici fiyat endeksi 200\'den 230\'a yükseldiğine göre çalışanın reel maaşındaki tam yüzdesel değişim kaçtır?', '%20 artış', ['%23 artış', '%15 artış', '%18 artış'], 'Enflasyon oranı (230 - 200) / 200 = %15\'tir. Reel değişim faktörü = 1,38 / 1,15 = 1,20 olduğundan reel maaş tam %20 artmıştır.'),
  ('Bir ekonomide ardışık iki yıl arasında nominal GSYH %12 artarken GSYH deflatörü %15 artmıştır. Bu ekonomideki reel GSYH değişimi için hangisi doğrudur?', 'Reel GSYH yaklaşık %2,61 oranında küçülmüştür', ['Reel GSYH tam olarak %3,00 oranında büyümüştür', 'Reel GSYH yaklaşık %2,61 oranında büyümüştür', 'Reel GSYH\'de herhangi bir yönlü değişim olmamıştır'], 'Reel büyüme faktörü = 1,12 / 1,15 = 0,97391 olduğundan değişim 0,97391 - 1 = -%2,61 (küçülme) olarak gerçekleşmiştir.'),
  ('Zincirleme fiyat endeksi değerleri (bir önceki yıl = 100) sırasıyla Yıl 1 için 110, Yıl 2 için 120 ve Yıl 3 için 125 olarak verilmiştir. Yıl 0 = 100 kabul edilirse Yıl 3\'ün sabit bazlı endeksi kaçtır?', '165', ['155', '160', '172,5'], 'Sabit bazlı endeks zincir halkalarının çarpımıyla bulunur: 100 x 1,10 x 1,20 x 1,25 = 110 x 1,50 = 165.'),
  ('Sabit bazlı bir fiyat endeksi ardışık dört yılda sırasıyla 100, 125, 150 ve 195 değerlerini almıştır. Bu serinin son yılına (4. yıl) ait zincirleme endeks değeri kaçtır?', '130', ['145', '120', '135'], 'Zincirleme endeks bir önceki yıla göre hesaplanır: (195 / 150) x 100 = 1,30 x 100 = 130.'),
  ('Tüketici Fiyat Endeksi (TÜFE) ile GSYH Deflatörü karşılaştırıldığında ithal tüketim mallarının fiyat artışları bu iki göstergeyi doğrudan nasıl etkiler?', 'TÜFE\'yi doğrudan artırır ancak yalnızca yurt içi üretimi ölçen GSYH deflatörünü doğrudan etkilemez', ['GSYH deflatörünü doğrudan artırır ancak hane halkı sepetini ölçen TÜFE\'yi etkilemez', 'Her iki fiyat endeksini de ithalatın dış ticaret hacmindeki payı kadar aynı oranda düşürür', 'İthal mallar döviz cinsinden fiyatlandığı için her iki endeksin de kapsamı dışında bırakılır'], 'TÜFE tüketicinin satın aldığı ithal malları kapsarken GSYH deflatörü yalnızca ülke sınırları içinde üretilen mal ve hizmetleri kapsar.'),
  ('Bir işletmenin cirosu temel yılda 400.000 TL iken cari yılda 660.000 TL\'ye çıkmıştır. Satılan ürünlerin Laspeyres fiyat endeksi 150 olduğuna göre Paasche miktar endeksi kaçtır?', '110', ['115', '105', '120'], 'Değer endeksi V = (660.000 / 400.000) x 100 = 165\'tir. V = (P_Laspeyres x Q_Paasche) / 100 bağıntısından Q_Paasche = (165 / 150) x 100 = 110 bulunur.'),
  ('Fiyat endekslerinin aksiyomatik özelliklerinden biri olan "zaman tersinirliği testi" (time reversal test) neyi şart koşar?', 'Baz dönem ile cari dönem yer değiştirdiğinde hesaplanan yeni endeksin, ilk endeksin çarpmaya göre tersine eşit olmasını', ['Fiyat endeksi ile miktar endeksi çarpıldığında toplam harcama değerindeki değişim oranının tam elde edilmesini', 'Bütün malların fiyatları aynı sabit katsayı ile çarpıldığında endeksin de aynı katsayı oranında değişmesini', 'Sepete fiyatı değişmeyen yeni bir mal eklendiğinde genel endeks değerinin hiçbir şekilde etkilenmemesini'], 'Zaman tersinirliği testine göre I(0,1) x I(1,0) = 1 (endeks 1 üzerinden yazılırsa) koşulu sağlanmalıdır; Fisher bunu sağlar ancak Laspeyres ve Paasche sağlamaz.'),
  ('Emekli maaşlarını güncellemek isteyen bir sosyal güvenlik kurumu, bütçe kısıtı altında tüketicilerin ikame olanaklarının çok düşük olduğu zorunlu gıda kalemlerinde refah kaybını önlemek için hangi endeksi tercih etmelidir?', 'Laspeyres fiyat endeksini, çünkü eski tüketim miktarlarını koruyacak gelir telafisini hedefler', ['Paasche fiyat endeksini, çünkü daralan tüketim miktarlarını esas alarak bütçe yükünü azaltır', 'Basit aritmetik fiyat ortalamasını, çünkü her mala harcama payından bağımsız eşit ağırlık verir', 'İhracat birim değer endeksini, çünkü dış piyasalardaki rekabetçi fiyat hareketlerini yansıtır'], 'Zorunlu mallarda ikame güç olduğundan, tüketicinin başlangıçtaki sepetini aynen satın alabilmesini sağlayan Laspeyres endeksi refah kaybına karşı daha koruyucudur.'),
  ('Bir ülkede yıllık nominal mevduat faizi %43 ve aynı yıl gerçekleşen enflasyon oranı %30\'dur. Tam Fisher denklemine göre gerçekleşen net reel faiz oranı yüzde kaçtır?', '%10', ['%13', '%11,5', '%9,5'], 'Tam Fisher formülü: (1 + r) = (1 + i) / (1 + pi) = 1,43 / 1,30 = 1,10. Buradan reel faiz r = 0,10 yani tam %10 olarak bulunur.'),
  ('Üç farklı baz yılına göre yayınlanmış bir endeks tablosunda 2016 bazlı seri 2019\'da 140; 2019 bazlı seri ise 2022\'de 150 değerindedir. Baz yılı 2022 = 100 yapılırsa 2016 yılının endeks değeri kaç olur?', '47,62', ['52,38', '45,00', '66,67'], '2016 = 100 iken 2022 endeksi 140 x 1,50 = 210\'dur. Baz 2022 = 100 yapıldığında 2016 değeri (100 / 210) x 100 = 47,62 olur.'),
  ('Teknolojik gelişmeler sayesinde bir bilgisayar modelinin işlemci hızı iki katına çıkarken satış fiyatı %10 artmıştır. Kalite düzeltmesi (hedonik düzeltme) yapılmayan standart bir fiyat endeksi bu durumu nasıl ölçer?', 'Gerçekte birim kalite başına fiyat düştüğü halde enflasyonu olduğundan yüksek (yukarı yönlü yanlı) ölçer', ['Ürünün teknik kapasitesi arttığı için fiyat artışını otomatik olarak sıfır kabul ederek yansız ölçer', 'Kalite artışını miktar düşüşü gibi algılayarak genel fiyat düzeyini olduğundan daha düşük gösterir', 'Teknolojik ürünleri hesaplama dışı bırakarak yalnızca hammadde fiyatları üzerinden endeks üretir'], 'Kalite iyileşmesi fiyata yansıdığında hedonik düzeltme yapılmazsa saf fiyat artışı abartılmış olur ve yukarı yönlü kalite yanlılığı doğar.'),
  ('Bir hane halkının aylık gıda harcaması 8.000 TL\'den 11.700 TL\'ye yükselmiştir. Aynı dönemde gıda fiyat endeksi 120\'den 156\'ya çıktığına göre hanenin reel gıda tüketim hacmi yüzde kaç değişmiştir?', '%12,5 artmıştır', ['%15,0 artmıştır', '%10,0 artmıştır', '%16,25 artmıştır'], 'Nominal harcama oranı 11.700 / 8.000 = 1,4625; fiyat artış oranı 156 / 120 = 1,30. Reel tüketim oranı = 1,4625 / 1,30 = 1,125 yani %12,5 artmıştır.'),
  ('Faktör tersinirliği testini (factor reversal test) sağlayan bir endeks formülünde hangi eşitlik her zaman geçerlidir?', 'Fiyat endeksi ile miktar endeksinin çarpımı (100\'e bölündüğünde) toplam değer endeksini verir', ['Temel dönem fiyatlarıyla cari dönem fiyatlarının toplamı her zaman miktarlar toplamına eşit olur', 'Laspeyres fiyat endeksi ile Paasche fiyat endeksinin farkı sıfıra yakınsamak zorundadır', 'Cari dönem harcamalarının temel dönem harcamalarına oranı sabit bir katsayıya eşit kalır'], 'Faktör tersinirliği testi P(0,1) x Q(0,1) = V(0,1) eşitliğini ifade eder ve Fisher ideal endeksi bu testi başarıyla sağlar.'),
  ('Bir sepette A, B ve C mallarının basit fiyat rölatifleri sırasıyla 120, 150 ve 180\'dir. Temel yılda bu mallara yapılan harcamalar sırasıyla 300 TL, 500 TL ve 200 TL ise sepetin Laspeyres fiyat endeksi kaçtır?', '147', ['150', '144', '153'], 'Toplam temel harcama 300 + 500 + 200 = 1000 TL (ağırlıklar 0,3; 0,5; 0,2). Laspeyres = 0,3(120) + 0,5(150) + 0,2(180) = 36 + 75 + 36 = 147.'),
  ('Üretici Fiyat Endeksi (ÜFE) ile Tüketici Fiyat Endeksi (TÜFE) arasındaki kavramsal farklara ilişkin aşağıdaki ifadelerden hangisi doğrudur?', 'ÜFE dolaylı vergileri (KDV, ÖTV) hariç tutarak üretici çıkış fiyatlarını izlerken TÜFE vergiler dahil nihai satış fiyatlarını izler', ['ÜFE yalnızca hizmet sektöründeki fiyat değişimlerini kapsarken TÜFE yalnızca sanayi mallarını kapsar', 'ÜFE ithal edilen nihai tüketim mallarını doğrudan sepetine dahil ederken TÜFE ithal malları dışarıda tutar', 'ÜFE hesaplamalarında ağırlıklar her zaman sabit kalırken TÜFE ağırlıkları her gün anlık olarak değiştirilir'], 'ÜFE yurt içi üreticilerin vergiler hariç fabrika/tarla çıkış fiyatlarını, TÜFE ise tüketicinin ödediği vergiler dahil perakende fiyatları ölçer.'),
  ('Temel yılda 1 dolar = 8 TL iken Türkiye\'de TÜFE 100 ve ABD\'de TÜFE 100\'dür. Cari yılda 1 dolar = 24 TL olmuş, Türkiye\'de TÜFE 360 ve ABD\'de TÜFE 120 düzeyine gelmiştir. Doların TL karşısındaki reel döviz kuru endeksi (temel yıl = 100) kaçtır?', '100', ['120', '90', '150'], 'Reel döviz kuru endeksi = Nominal Kur Endeksi x (Yabancı TÜFE / Yurt İçi TÜFE) = (24 / 8) x 100 x (120 / 360) = 300 x (1/3) = 100.'),
  ('Bir malın fiyatı üç ardışık yılda sırasıyla 25 TL, 40 TL ve 36 TL olmuştur. İkinci yıl baz yılı (100) olarak seçilirse birinci ve üçüncü yılların endeks değerleri sırasıyla kaç olur?', '62,5 ve 90', ['60,0 ve 90', '62,5 ve 85', '75,0 ve 92'], 'Baz yılı fiyatı 40 TL olduğundan 1. yıl endeksi = (25 / 40) x 100 = 62,5; 3. yıl endeksi = (36 / 40) x 100 = 90 olur.'),
  ('Geleneksel süpermarketler yerine aynı kalitedeki ürünü daha ucuza satan indirim marketlerinin yaygınlaştığı bir ekonomide, satış noktası örnekleminde güncelleme yapılmazsa fiyat endeksinde hangi yanlılık ortaya çıkar?', 'Satış noktası ikame yanlılığı nedeniyle enflasyon olduğundan daha yüksek ölçülür', ['Baz yılı kaydırma hatası nedeniyle genel fiyat düzeyi negatif değerler almaya başlar', 'Mevsimsel dalgalanma yanlılığı nedeniyle tarım fiyatları olduğundan düşük görünür', 'Birim değer yanlılığı nedeniyle lüks tüketim mallarının ağırlığı sıfıra düşer'], 'Tüketicilerin daha ucuz satış noktalarına geçişini yakalayamayan sabit mağaza örneklemi yukarı yönlü satış noktası ikame yanlılığı yaratır.'),
  ('Aylık enflasyonun üst üste üç ay boyunca sırasıyla %4, %5 ve %0 olarak gerçekleştiği bir çeyrek dönemde, üç aylık birikimli (bileşik) fiyat artışı yüzde kaçtır?', '%9,20', ['%9,00', '%9,25', '%8,80'], 'Üç aylık bileşik faktör = 1,04 x 1,05 x 1,00 = 1,0920. Dolayısıyla birikimli fiyat artışı %9,20\'dir.'),
  ('Bir ülkede tüketici fiyat endeksi yıl başında 400 iken yıl sonunda 500 olmuştur. Yıl başında 200.000 TL nakit parası olan ve bunu faizsiz olarak kasada tutan bir kişinin parasının yıl sonundaki reel satın alma gücü yıl başı fiyatlarıyla kaç TL\'ye düşmüştür?', '160.000 TL', ['150.000 TL', '165.000 TL', '175.000 TL'], 'Fiyat düzeyi 500 / 400 = 1,25 katına çıktığından, 200.000 TL\'nin yıl başı fiyatlarıyla reel karşılığı 200.000 / 1,25 = 160.000 TL\'dir.'),
  ('Bir sanayi şirketi son beş yıldaki satış gelirlerini "2019 yılı sabit fiyatlarıyla" raporlamıştır. Finansal analistin bu ifadeyi yorumlarken varacağı en doğru sonuç hangisidir?', 'Gelir serisindeki değişimler fiyat artışlarından arındırılmış olup yalnızca fiziksel satış hacmi ve ürün karması değişimini yansıtmaktadır', ['Şirket beş yıl boyunca müşterilerine uyguladığı etiket fiyatlarını 2019 düzeyinde dondurarak hiç zam yapmamıştır', 'Şirketin üretim maliyetleri beş yıl boyunca enflasyon oranının tam iki katı hızla artış göstermiştir', 'Raporlanan tutarlar vergi öncesi kar rakamlarının döviz kuruna bölünmesiyle elde edilmiş nominal değerlerdir'], 'Sabit fiyatlarla raporlama, cari ciroların uygun fiyat deflatörüne bölünmesiyle enflasyon etkisinin giderildiğini ve reel hacim değişiminin izlendiğini gösterir.'),
  ('İki mal grubundan oluşan bir endekste konut grubunun ağırlığı %25, diğer tüm malların ağırlığı %75\'tir. Konut fiyatları %60 artarken endeksin tamamı %30 arttığına göre diğer tüm malların fiyatları ortalama yüzde kaç artmıştır?', '%20', ['%22,5', '%15', '%25'], '0,25 x 60 + 0,75 x X = 30 => 15 + 0,75X = 30 => 0,75X = 15 => X = %20 olarak hesaplanır.'),
  ('Arz yönlü olumlu bir teknoloji şoku nedeniyle bir malın hem fiyatı hızla düşüyor hem de piyasadaki tüketim miktarı hızla artıyorsa Laspeyres ve Paasche fiyat endeksleri nasıl davranır?', 'Fiyatı düşen malın cari miktarı çok daha büyük olduğu için Paasche endeksi Laspeyres endeksinden daha düşük çıkar', ['Fiyatı düşen malın eski miktarı daha büyük olduğu için Laspeyres endeksi Paasche endeksinden daha düşük çıkar', 'Arz şoklarında miktar ağırlıkları sadeleştiği için her iki endeks de matematiksel olarak eşit çıkar', 'Paasche endeksi negatif değer alırken Laspeyres endeksi her zaman 100\'ün üzerinde kalır'], 'Tüketiciler ucuzlayan maldan cari dönemde çok daha fazla tükettiği için Paasche ucuzlayan mala daha yüksek ağırlık verir ve L > P eşitsizliği daha da belirginleşir.'),
  ('Temel yıl harcama değerleri 200 TL ve 300 TL olan iki malın cari yıldaki harcama değerleri sırasıyla 330 TL ve 390 TL olmuştur. Birinci malın basit fiyat endeksi 150, ikinci malın basit fiyat endeksi 130 ise Paasche fiyat endeksi kaçtır?', '138,46', ['140,00', '136,50', '141,20'], 'Paasche payı = 330 + 390 = 720. Paydası = (330 / 1,50) + (390 / 1,30) = 220 + 300 = 520. Paasche = (720 / 520) x 100 = 138,46.'),
  ('Dört çeyrekte nominal fiyatı 90 TL sabit kalan bir hizmetin çeyreklik fiyat endeksi sırasıyla 100, 120, 150 ve 180 olmuştur. Birinci çeyrek baz alındığında bu hizmetin dört çeyreklik ortalama reel fiyatı kaç TL\'dir?', '68,75 TL', ['67,50 TL', '70,25 TL', '65,00 TL'], 'Çeyreklik reel fiyatlar: Q1 = 90/1,0 = 90 TL; Q2 = 90/1,2 = 75 TL; Q3 = 90/1,5 = 60 TL; Q4 = 90/1,8 = 50 TL. Aritmetik ortalaması = (90 + 75 + 60 + 50) / 4 = 275 / 4 = 68,75 TL.'),
  ('Piyasaya ilk kez sürülen akıllı saat veya elektrikli otomobil gibi yenilikçi ürünlerin fiyat endeksi sepetine çok geç dahil edilmesi hangi ölçüm sorununa yol açar?', 'Yeni ürünlerin ilk çıktıktan sonraki hızlı fiyat düşüşleri kaçırıldığı için yeni ürün yanlılığı (yukarı yönlü sapma) oluşur', ['Sepetteki mal sayısı değişmediği için endeks hesaplamaları istatistiksel olarak tamamen hatasız kalır', 'Yeni ürünlerin başlangıç fiyatları düşük olduğu için enflasyon oranı olduğundan daha düşük hesaplanır', 'Eski ürünlerin fiyatları kendiliğinden sıfırlandığı için Paasche endeksi tanımsız hale gelir'], 'Yeni ürünler piyasaya yüksek fiyattan girip ölçek ekonomisiyle ucuzladığından, sepete geç alınmaları bu ucuzlama sürecinin endekse yansımasını engeller.'),
  ('Bir kamu ihalesinde eskalasyon (fiyat farkı) katsayısı %40 işçilik endeksi ve %60 malzeme endeksi ağırlığıyla hesaplanmaktadır. Sözleşme tarihine göre işçilik endeksi %50, malzeme endeksi %25 arttığına göre toplam fiyat farkı oranı yüzde kaçtır?', '%35', ['%37,5', '%32,5', '%40'], 'Ağırlıklı artış oranı = 0,40 x %50 + 0,60 x %25 = %20 + %15 = %35 olarak hesaplanır.'),
  ('Bir hisse senedinin fiyatı birinci yıl %50 artmış, ikinci yıl ise %33,33 (üçte bir oranında) düşmüştür. Bu hisse senedinin iki yıllık bileşik yıllık büyüme hızı (CAGR) yüzde kaçtır?', '%0', ['%8,33', '%5,00', '-%2,50'], '100 birimlik hisse 1. yıl 150 olur, 2. yıl 150 x (2/3) = 100\'e döner. Başlangıç ve bitiş eşit olduğundan CAGR = (100/100)^(1/2) - 1 = %0\'dır.'),
  ('Yıllık bileşik %6 hızla büyüyen bir portföyün başlangıç değeri 50.000 TL\'dir. 72 kuralına göre bu portföyün değerinin 200.000 TL\'ye (dört katına) ulaşması yaklaşık kaç yıl sürer?', '24 yıl', ['12 yıl', '18 yıl', '36 yıl'], 'Bir kez ikiye katlanma süresi = 72 / 6 = 12 yıldır. Dört katına çıkmak iki kez ikiye katlanmak (50 bin -> 100 bin -> 200 bin) olduğundan 12 + 12 = 24 yıl sürer.'),
  ('İki farklı ülkeden A ülkesinin genç (0-14) nüfus oranı çok yüksekken, B ülkesinin yaşlı (65+) nüfus oranı çok yüksektir. Her iki ülkenin "kaba ölüm hızı" birbirine eşit çıkarsa bu durum nasıl açıklanır?', 'Kaba ölüm hızı yaş yapısından etkilenir; B ülkesinde yaşa özel ölüm oranları daha düşük olsa bile yaşlı nüfus payının yüksekliği kaba ölüm hızını yukarı çeker', ['Her iki ülkedeki hastanelerin yatak kapasitesi ve ortalama yaşam beklentisi matematiksel olarak birebir aynıdır', 'Kaba ölüm hızı hesaplanırken 65 yaş üstü ölümler formül gereği her zaman kapsam dışında tutulmaktadır', 'A ülkesinde bebek ölümleri sıfır iken B ülkesinde genç ölümleri toplam ölümlerin tamamını oluşturmaktadır'], 'Kaba ölüm hızı nüfusun yaş dağılımına duyarlıdır; sağlık koşulları çok iyi olan yaşlı bir toplumun kaba ölüm hızı, genç bir toplumunki kadar yüksek çıkabilir.'),
  ('Türkiye İstatistik Kurumu (TÜİK) yöntemine göre bir kentin yıl sonu nüfusu (göç edenler dahil) 505.000\'dir. Yıl içinde kente 20.000 kişi göç gelmiş, kentten 10.000 kişi göç gitmiştir. TÜİK net göç hızı formülüne göre kentin net göç hızı binde kaçtır?', 'Binde 20', ['Binde 19,8', 'Binde 20,2', 'Binde 10'], 'TÜİK formülünde payda "göç edebilecek nüfus" olan M = N_yılsonu - (Gelen - Giden)/2 = 505.000 - (10.000 / 2) = 500.000\'dir. Net göç hızı = (10.000 / 500.000) x 1.000 = binde 20.'),
  ('Standart uluslararası yıl ortası nüfus yaklaşımıyla, yıl ortası nüfusu 250.000 olan bir yerleşim yerine yıl içinde 8.500 kişi gelmiş ve 3.500 kişi ayrılmıştır. Bu yerleşim yerinin kaba net göç hızı binde kaçtır?', 'Binde 20', ['Binde 14', 'Binde 34', 'Binde 22'], 'Net göç = 8.500 - 3.500 = +5.000 kişi. Yıl ortası nüfusa göre kaba net göç hızı = (5.000 / 250.000) x 1.000 = binde 20\'dir.'),
  ('Bir yatırım fonu ilk 2 yıl boyunca yılda %21 büyümüş, sonraki 2 yıl boyunca ise hiç büyümemiştir (%0). Bu fonun 4 yıllık bileşik yıllık büyüme hızı (CAGR) yüzde kaçtır?', '%10', ['%10,5', '%9,5', '%11'], '4 yıllık toplam büyüme çarpanı = 1,21 x 1,21 x 1 x 1 = 1,4641 = (1,10)^4. Dolayısıyla 4 yıllık CAGR = (1,4641)^(1/4) - 1 = %10\'dur.'),
  ('Sabit bir büyüme oranı (r) için tam ikiye katlanma süresi t = ln(2) / ln(1 + r) formülüyle hesaplanır. Küçük büyüme oranlarında ln(2) yaklaşık 0,693 iken finansal pratikte 69,3 yerine "72 kuralı"nın tercih edilmesinin iki temel nedeni nedir?', '72 sayısının 2, 3, 4, 6, 8, 9, 12 gibi çok sayıda tam böleni olması ve kesikli bileşik faizde %6-%10 aralığında 69,3\'ten daha isabetli yaklaşım vermesi', ['Doğal logaritma tabanı e sayısının finansal piyasalarda 2,718 yerine tam 3,00 olarak kabul edilmesi', 'Merkez bankalarının bir mali yılı 365 gün yerine 360 gün üzerinden 5\'e bölerek 72 sayısına ulaşması', '72 sayısının enflasyonist ortamlarda negatif faiz oranlarını otomatik olarak pozitif değere çevirmesi'], 'ln(1+r) ifadesi r büyüdükçe r\'den küçük kaldığından (örneğin %8\'de tam süre 9,006 yıldır), 72/8 = 9 işlemi hem tam bölünür hem de kesikli bileşiklenmede çok daha yakındır.'),
  ('Bir ülkede yıl başında nüfus 80.000.000\'dur. Yıl içinde 1.100.000 canlı doğum, 450.000 ölüm gerçekleşmiş; ülkeye 350.000 göçmen gelirken ülkeden 200.000 kişi göç etmiştir. Nüfus denge denklemine göre yıl sonu nüfusu kaçtır?', '80.800.000', ['80.650.000', '80.500.000', '81.100.000'], 'N_son = N_baş + (Doğum - Ölüm) + (Gelen Göç - Giden Göç) = 80.000.000 + (1.100.000 - 450.000) + (350.000 - 200.000) = 80.000.000 + 650.000 + 150.000 = 80.800.000.'),
  ('Demografik dönüşüm sürecinde "demografik fırsat penceresi" (demographic dividend) hangi yaş yapısı değişimi sonucunda ortaya çıkar?', 'Doğurganlığın düşmesiyle çocuk bağımlılık oranının hızla gerilemesi, yaşlı nüfusun ise henüz çok artmamış olması sayesinde çalışma çağı nüfus payının zirveye çıkması', ['Emeklilik yaşının düşürülmesiyle yaşlı bağımlılık oranının çalışma çağı nüfusunu ikiye katlaması', 'Kaba ölüm hızının kaba doğum hızının üzerine çıkarak toplam nüfusun hızla yarıya inmesi', 'Kırsal kesimden kentlere yapılan tüm iç göçlerin idari kararlarla tamamen durdurulması'], 'Doğum oranları düştükten sonraki birkaç on yılda toplam yaş bağımlılık oranı tarihi dip seviyesine iner ve çalışma çağındaki nüfusun payı ekonomik büyümeyi destekler.'),
  ('Bir ülkede toplam nüfusun %20\'si 0-14 yaş grubunda, %12\'si ise 65 ve üzeri yaş grubundadır. Bu ülkenin toplam yaş bağımlılık oranı yaklaşık yüzde kaçtır?', '%47,06', ['%32,00', '%45,12', '%38,50'], 'Çalışma çağı nüfusunun payı = 100 - (20 + 12) = %68\'dir. Toplam bağımlılık oranı = [(20 + 12) / 68] x 100 = (32 / 68) x 100 = %47,06\'dır.'),
  ('Bir teknoloji şirketinin AR-GE harcamaları 5 yıl boyunca yıllık bileşik %15 hızla büyümüştür. Aynı dönemde sektörel AR-GE maliyet endeksi yıllık bileşik %5 arttığına göre şirketin reel AR-GE hacminin yıllık bileşik büyüme hızı yaklaşık (tam oranla) yüzde kaçtır?', '%9,52', ['%10,00', '%9,00', '%10,25'], 'Reel yıllık bileşik büyüme faktörü = (1 + Nominal CAGR) / (1 + Enflasyon CAGR) = 1,15 / 1,05 = 1,095238. Buradan reel CAGR = %9,52 bulunur.'),
  ('Bir fonun 3 yıllık dönemdeki yıllık getirileri sırasıyla +%30, -%20 ve +%25 olarak gerçekleşmiştir. Bu fonun aritmetik ortalama getirisi (AO) ile bileşik yıllık büyüme hızı (CAGR) karşılaştırıldığında hangisi doğrudur?', 'AO = %11,67 iken CAGR yaklaşık %9,14\'tür; getirilerde değişkenlik (standart sapma > 0) olduğu için CAGR aritmetik ortalamadan küçüktür', ['AO = %11,67 ve CAGR = %11,67\'dir; üç yıllık serilerde aritmetik ve geometrik ortalamalar her zaman çakışır', 'CAGR yaklaşık %13,20 iken AO = %11,67\'dir; pozitif yılların sayısı negatif yıllardan fazla olduğunda CAGR daha büyük çıkar', 'AO = %10,00 iken CAGR = %8,50\'dir; negatif getiri bulunan hiçbir seride tam geometrik ortalama hesaplanamaz'], 'AO = (30 - 20 + 25)/3 = %11,67. Çarpan = 1,30 x 0,80 x 1,25 = 1,30; CAGR = (1,30)^(1/3) - 1 = %9,14. AO >= GO eşitsizliği gereği dalgalı serilerde CAGR daima daha küçüktür.'),
  ('Genel doğurganlık hızı (general fertility rate), bir yıldaki canlı doğum sayısının doğurgan çağdaki (15-49 yaş) kadın nüfusuna oranlanmasıyla (binde olarak) bulunur. Toplam nüfusu 1.000.000 olan bir ilde nüfusun yarısı kadın, kadınların %50\'si 15-49 yaş grubundadır. Yıllık canlı doğum sayısı 15.000 ise genel doğurganlık hızı binde kaçtır?', 'Binde 60', ['Binde 15', 'Binde 30', 'Binde 45'], 'Kadın nüfus = 500.000; 15-49 yaş kadın nüfus = 500.000 x 0,50 = 250.000. Genel doğurganlık hızı = (15.000 / 250.000) x 1.000 = binde 60.'),
  ('Bir ülkenin Gayrisafi Yurt İçi Hasılası yıllık bileşik %4,5 hızla büyürken nüfusu yıllık bileşik %1,5 hızla artmaktadır. 72 kuralı ve yaklaşık büyüme farkı kullanıldığında kişi başına düşen GSYH yaklaşık kaç yılda iki katına çıkar?', '24 yılda', ['16 yılda', '18 yılda', '30 yılda'], 'Kişi başına GSYH büyüme hızı yaklaşık %4,5 - %1,5 = %3,0\'tür. 72 kuralına göre ikiye katlanma süresi = 72 / 3 = 24 yıldır.'),
  ('Bir belediye başkanı son 10 yılda ilçenin su tüketiminin toplamda %100 arttığını belirterek "yıllık %10 su tüketim artışı var" demiştir. İstatistiksel danışmanın bu ifadeye yapacağı en doğru düzeltme hangisidir?', 'Toplam %100 artış 10 yılda ikiye katlanma demektir; bileşik büyüme etkisinden dolayı gerçek yıllık artış hızı (CAGR) %10 değil yaklaşık %7,18\'dir', ['10 yılda %100 artış yaşandığında yıllık bileşik büyüme hızı %10\'dan daha yüksek olup yaklaşık %12,5 düzeyindedir', 'Su tüketimi fiziksel bir hacim ölçüsü olduğu için yüzdesel veya bileşik büyüme formülleriyle ifade edilemez', 'Belediye başkanının hesabı tam doğrudur çünkü 10 yıllık serilerde basit bölme ile bileşik büyüme her zaman aynı sonucu verir'], '10 yılda 2 katına çıkan bir büyüklükte 72 kuralıyla bile hız ~%7,2 (tam değeri 2^(1/10) - 1 = %7,18) bulunur; yıllık %10 bileşik artış olsaydı tüketim 2,59 katına çıkardı.'),
  ('Bir ilde yıl içinde 24.000 canlı doğum gerçekleşmiş ve aynı yıl 1 yaşını doldurmadan ölen bebek sayısı 360 olmuştur. Bu ilin bebek ölüm hızı binde kaçtır?', 'Binde 15', ['Binde 12', 'Binde 1,5', 'Binde 18'], 'Bebek ölüm hızı = (1 yaş altı bebek ölümü / Canlı doğum sayısı) x 1.000 = (360 / 24.000) x 1.000 = binde 15.'),
  ('Demografide "Toplam Doğurganlık Hızı"nın (Total Fertility Rate - TFR) gelişmiş sağlık koşullarında nüfusun kendini yenileme düzeyi olan "2,1 çocuk" sınırının altında kalması uzun vadede neye işaret eder?', 'Dış göç alınmadığı takdirde nüfusun yaşlanacağına ve uzun vadede mutlak nüfus büyüklüğünün azalmaya başlayacağına', ['Ülkedeki toplam nüfusun bir sonraki takvim yılından itibaren derhal yarı yarıya düşeceğine', 'Bebek ölüm hızının kadın başına düşen doğum sayısından daha yüksek seyrettiğine', 'Çocuk bağımlılık oranının yaşlı bağımlılık oranını kalıcı olarak geçeceğine'], 'Kuşakların kendini yenileyebilmesi için anne-baba yerine geçecek 2 çocuk ve yetişkinliğe ulaşamama riskini telafi edecek 0,1 pay (toplam ~2,1) gerekir; bunun altı uzun vadeli küçülme eğilimidir.'),
  ('Bir şirketin cirosu 2017\'de 50 milyon TL, 2019\'da 95 milyon TL, 2020\'de 70 milyon TL ve 2023\'te 160 milyon TL olmuştur. 2017 - 2023 döneminin (6 yıllık) bileşik yıllık büyüme hızı (CAGR) hesaplanırken hangi ara yıl verileri sonucu doğrudan değiştirmez?', '2019 ve 2020 yıllarına ait ara ciro değerleri', ['2017 yılına ait başlangıç cirosu ve dönem sayısı', '2023 yılına ait dönem sonu cirosu', 'Dönem uzunluğu olan 6 yıllık zaman aralığı'], 'CAGR yalnızca başlangıç değeri (V_2017 = 50), bitiş değeri (V_2023 = 160) ve dönem sayısına (n = 6) bağlıdır; ara yıllardaki dalgalanmalar hesaplamaya girmez.'),
  ('Bir ormanda ağaç varlığı her yıl bileşik %3 oranında azalmaktadır. 72 kuralının azalan büyüklüklere (yarılanma süresine) uyarlanmasıyla bu ormandaki ağaç varlığı yaklaşık kaç yılda yarıya düşer?', '24 yılda', ['20 yılda', '36 yılda', '18 yılda'], 'Üstel azalmada yarılanma süresi de ln(0,5) = -ln(2) simetrisi nedeniyle yaklaşık 70 veya 72 kuralıyla bulunur: 72 / 3 = 24 yıl.'),
  ('CAGR göstergesinin kurumsal performans analizlerinde tek başına kullanılmasının yarattığı en önemli analitik kısıt (sınırlılık) nedir?', 'Yalnızca ilk ve son döneme baktığı için ara dönemlerdeki şiddetli krizleri, oynaklığı ve seçilen başlangıç/bitiş yılına aşırı duyarlılığı gizlemesi', ['Negatif olmayan pozitif ciro serilerinde bile matematiksel olarak birden fazla gerçek kök üretmesi', 'Enflasyonun sıfır olduğu ekonomilerde bile nominal değerleri kendiliğinden sıfıra yakınsatması', 'Yalnızca çift sayılı dönem uzunluklarında hesaplanıp tek sayılı yıllarda tanımsız kalması'], 'CAGR ara dönem bilgisini tamamen yutar; örneğin baz yılı düşük bir kriz yılı seçilirse CAGR yapay biçimde çok yüksek görünür (baz etkisi).'),
  ('İki komşu kentten K kenti 600.000 nüfusa, L kenti 400.000 nüfusa sahiptir. K kenti kaba doğum hızı binde 14, L kenti kaba doğum hızı binde 24\'tür. İki kent tek bir büyükşehir çatısında birleştirilirse yeni büyükşehrin kaba doğum hızı binde kaç olur?', 'Binde 18', ['Binde 19', 'Binde 17,5', 'Binde 20'], 'K\'deki doğumlar = 600 x 14 = 8.400; L\'deki doğumlar = 400 x 24 = 9.600. Toplam doğum = 18.000; toplam nüfus = 1.000.000. Birleşik kaba doğum hızı = 18.000 / 1.000 = binde 18.'),
  ('Sürekli bileşik büyüme modelinde N(t) = N0 * e^(r*t) bağıntısıyla büyüyen bir bakteri kültürünün anlık büyüme hızı r = %6,93 (0,0693) olarak ölçülmüştür. ln(2) = 0,693 alındığında kültür tam olarak kaç saatte iki katına çıkar?', '10 saatte', ['10,39 saatte', '9,5 saatte', '12 saatte'], 'Sürekli bileşik büyümede tam ikiye katlanma süresi t = ln(2) / r = 0,693 / 0,0693 = 10 saattir (69,3 kuralının tam karşılığı).'),
  ('Bir ilin "brüt göç" (toplam göç hacmi) kavramı ile "net göç" kavramı arasındaki fark nedir?', 'Brüt göç ile gelen ve ilden giden göçmenlerin toplamını ifade ederken, net göç gelen ile giden arasındaki farkı ifade eder', ['Brüt göç yalnızca uluslararası dış göçleri kapsarken, net göç yalnızca iller arası iç göçleri kapsar', 'Brüt göç vergi mükellefi olan çalışan göçmenleri, net göç ise emekli ve öğrenci göçmenleri ölçer', 'Brüt göç her zaman negatif veya sıfır değer alırken, net göç her zaman pozitif değer almak zorundadır'], 'Toplam göç hareketliliğini (mobiliteyi) ölçen brüt göç G_gelen + G_giden toplamıdır; nüfus değişimine etki eden net göç ise G_gelen - G_giden farkıdır.'),
  ('Bir e-ticaret sitesinin aktif kullanıcı sayısı ilk 3 yılda yıllık bileşik %20 büyümüş, takip eden 3 yılda ise yıllık bileşik %5 büyümüştür. Altı yıllık dönemin tamamı için yıllık bileşik büyüme hızı (CAGR) hangi ifadeye eşittir?', 'karekök(1,20 x 1,05) - 1 (yaklaşık %12,25)', ['(0,20 + 0,05) / 2 (tam %12,50)', '(1,20^3 + 1,05^3) / 6 - 1', 'karekök(0,20 x 0,05) (tam %10,00)'], '6 yıllık çarpan = 1,20^3 x 1,05^3 = (1,20 x 1,05)^3 = 1,26^3. 6. dereceden kökü alındığında (1,26^3)^(1/6) - 1 = (1,26)^(1/2) - 1 = %12,25 bulunur.'),
  ('Bir ülkenin kaba doğum hızı binde 15, kaba ölüm hızı binde 15 ve net göçü sıfırdır. Ancak ülkede doğurganlık çağındaki kadın kuşağı çok kalabalık olduğu için toplam nüfus bir süre daha sabit kalmayıp değişmektedir. "Nüfus momentumu" kavramına göre doğum oranı yenilenme düzeyinde kalsa bile genç yaş yapısına sahip toplumlarda ne görülür?', 'Geçmişteki yüksek doğurganlıktan gelen geniş genç kuşaklar ebeveynlik çağına girdikçe toplam nüfus bir süre daha artmaya devam eder', ['Doğurganlık oranı düştüğü gün toplam nüfus hiçbir gecikme olmaksızın aynı yıl küçülmeye başlar', 'Yaşlı bağımlılık oranı bir yıl içinde sıfıra inerek emeklilik fonlarının tüm yükünü ortadan kaldırır', 'Bebek ölüm hızı kendiliğinden kaba ölüm hızının iki katına çıkarak nüfus artışını durdurur'], 'Genç yaş yapısına sahip nüfuslarda doğurganlık yenilenme sınırına inse bile anne-baba adaylarının sayıca çokluğu nedeniyle doğum sayısı bir süre yüksek kalır; buna pozitif nüfus momentumu denir.'),
  ('Bir yatırım 72 kuralına göre 6 yılda iki katına çıkmaktadır. Aynı yıllık bileşik getiri oranıyla başlangıçtaki 25.000 TL\'lik yatırım 18 yılın sonunda yaklaşık kaç TL olur?', '200.000 TL', ['150.000 TL', '100.000 TL', '225.000 TL'], '18 yıl içinde 18 / 6 = 3 kez ikiye katlanma gerçekleşir. Yatırım değeri = 25.000 x 2^3 = 25.000 x 8 = 200.000 TL olur.'),
  ('Yıl ortası nüfusu 2.000.000 olan bir bölgede yıllık doğal nüfus artışı +16.000 kişi olmuş, ancak bölgenin yıl sonu nüfusu yıl başı nüfusuna göre yalnızca +6.000 kişi artmıştır. Bu bölgenin kaba net göç hızı binde kaçtır?', 'Binde -5', ['Binde +5', 'Binde -11', 'Binde -3'], 'Toplam artış (+6.000) = Doğal artış (+16.000) + Net göç => Net göç = -10.000 kişidir. Kaba net göç hızı = (-10.000 / 2.000.000) x 1.000 = binde -5.'),
  ('İki farklı bölgedeki kanser ölüm riskini adil biçimde karşılaştırmak isteyen bir halk sağlığı uzmanı, emekli nüfusun yoğun olduğu sahil kasabası ile üniversite öğrencilerinin yoğun olduğu kenti kıyaslarken hangi göstergeyi kullanmalıdır?', 'Yaşa göre standartlaştırılmış (yaş düzeltmeli) ölüm hızını', ['Doğrudan yıl ortası nüfusa bölünen kaba ölüm hızını', 'Toplam yaş bağımlılık oranının kaba doğum hızına oranını', 'Net göç hızı ile kaba doğum hızının aritmetik ortalamasını'], 'Emekli kasabasında sırf yaşlı oranı yüksek olduğu için kaba ölüm hızı yüksek çıkar; yaş etkisini arındırıp gerçek sağlık riskini ölçmek için yaşa göre standartlaştırılmış ölüm hızı şarttır.'),
  ('Bir ülkede çocuk bağımlılık oranı %30, toplam yaş bağımlılık oranı ise %48\'dir. Bu ülkede 65 ve üzeri yaştaki nüfus 9 milyon kişi olduğuna göre 0-14 yaş grubundaki çocuk nüfus kaç milyondur?', '15 milyon', ['13,5 milyon', '18 milyon', '12 milyon'], 'Yaşlı bağımlılık oranı = %48 - %30 = %18\'dir. %18 oran 9 milyon kişiye karşılık geldiğine göre çalışma çağı nüfusu = 9 / 0,18 = 50 milyondur. Çocuk nüfus = 50 x 0,30 = 15 milyondur.'),
  ('Bir ülkede yaşlı bağımlılık oranı %18, çocuk bağımlılık oranı ise %32 olarak açıklanmıştır. Çalışma çağındaki (15-64 yaş) nüfus 36 milyon kişi olduğuna göre ülkedeki bağımlı nüfus toplamı kaç milyondur?', '18 milyon', ['16,2 milyon', '19,8 milyon', '15 milyon'], 'Toplam yaş bağımlılık oranı = %18 + %32 = %50\'dir. Çalışma çağı nüfusu 36 milyon olduğundan toplam bağımlı nüfus = 36 x 0,50 = 18 milyondur.'),
  ('Bir ülkenin doğurganlık oranı tam yenilenme düzeyine düşmüş olsa bile doğurganlık çağındaki kadın kuşağı çok kalabalık olduğu için toplam nüfus bir süre daha artmaya devam etmektedir. Demografide bu olguya ne ad verilir ve nedeni nedir?', 'Pozitif nüfus momentumu; geçmişteki yüksek doğurganlıktan gelen geniş genç kuşakların ebeveynlik çağına girmesiyle doğum sayısının yüksek kalması', ['Demografik çöküş tuzağı; yaşlı bağımlılık oranının bir yıl içinde sıfıra inerek ölüm sayılarını tamamen durdurması', 'Tersine göç dalgası; kaba doğum hızı ile kaba ölüm hızının çarpımının her zaman 100\'e yakınsaması', 'Malthusyen sıçrama; gıda üretiminin aritmetik artarken bebek ölüm hızının geometrik olarak artması'], 'Genç yaş yapısına sahip toplumlarda kadın başına doğum düşse bile anne adaylarının sayıca çokluğu toplam nüfusu on yıllarca artırmaya devam eder; buna nüfus momentumu denir.'),
];
